'use strict';
const ATLAS_ENTRY_HASH=location.hash;
const D=JSON.parse(document.getElementById('atlas-data').textContent), A=JSON.parse(document.getElementById('archive-data').textContent), W=JSON.parse(document.getElementById('world-data').textContent);
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>Array.from(r.querySelectorAll(s));
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(n,d=0)=>n==null||!Number.isFinite(Number(n))?'Not disclosed':Number(n).toLocaleString('en-US',{maximumFractionDigits:d,minimumFractionDigits:d});
const compact=n=>n==null?'Not disclosed':Math.abs(n)>=1e6?fmt(n/1e6,2)+'M':Math.abs(n)>=1000?fmt(n/1000,1)+'k':fmt(n);
const gw=n=>n==null?'—':fmt(n/1000,3), money=(n,d=1)=>n==null?'Not disclosed':'$'+fmt(n,d)+'B';
const qs=(obj)=>Object.entries(obj).map(([k,v])=>`${esc(k)}="${esc(v)}"`).join(' ');
const site=id=>D.sites.find(x=>x.id===id), company=id=>D.companies.find(x=>x.id===id), source=id=>D.sources.find(x=>x.id===id);
const ids=(x)=>Array.isArray(x)?x:(String(x||'').match(/[SN]\d{2}/g)||[]);
const srefs=x=>`<span class="source-links">${[...new Set(ids(x))].filter(id=>source(id)).map(id=>`<button class="source-chip" data-action="source" data-id="${id}" title="${esc(source(id).title)}">${id}</button>`).join('')}</span>`;
const rolePill=s=>s.review==='reviewed-model'?'<span class="pill model">Reviewed model</span>':s.review==='primary-noncomparable'?'<span class="pill primary">Native-unit disclosure</span>':s.review==='contract-record'?'<span class="pill target">Contract record</span>':'<span class="pill archive">Imported estimate</span>';
const phasePill=s=>s.snapshot?'<span class="pill model">Operating estimate</span>':s.target?'<span class="pill target">Projected only</span>':'<span class="pill">Unquantified AI MW</span>';
const icon=(name)=>`<svg class="icon" width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${({overview:'<path d="M3 11 12 3l9 8v10h-7v-7h-4v7H3Z"/>',globe:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18M5 6.5h14M5 17.5h14"/>',facilities:'<path d="M3 21V9h7V3h11v18H3Zm7-12v12M14 7h3M14 11h3M14 15h3M6 13v2M6 18v1"/>',companies:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',contracts:'<circle cx="5" cy="12" r="3"/><circle cx="19" cy="5" r="3"/><circle cx="19" cy="19" r="3"/><path d="m8 11 8-5M8 13l8 5"/>',costs:'<path d="M3 20h18M5 16v-5M10 16V5M15 16V9M20 16V3"/>',investment:'<path d="M3 17 9 11l4 3 8-10M15 4h6v6M3 21h18"/>',reports:'<path d="M5 3h10l4 4v14H5V3Zm10 0v5h4M8 12h8M8 16h8"/>',data:'<ellipse cx="12" cy="5" rx="9" ry="3"/><path d="M3 5v14c0 4 18 4 18 0V5M3 12c0 4 18 4 18 0"/>',stories:'<path d="m4 3 16 9-16 9V3Z"/>',watchlist:'<path d="m12 3 3 6 7 1-5 5 1 7-6-4-6 4 1-7-5-5 7-1Z"/>'})[name]||'<circle cx="12" cy="12" r="8"/>'}</svg>`;
const NAV=[['overview','The landscape'],['globe','Globe explorer'],['facilities','Facility directory'],['companies','Company universe'],['contracts','Contracts & connections'],['costs','Costs & hardware'],['investment','Investment lens'],['stories','Guided explorations'],['reports','Full report library'],['data','Data room & sources']];
let storageOK=true;let saved={favorites:[],notes:{},compare:[]};try{saved={...saved,...JSON.parse(localStorage.getItem('compute-atlas-v3')||'{}')};}catch{storageOK=false;}
const state={view:'overview',filter:{q:'',company:'all',country:'all',review:'all',stage:'all'},layout:'table',sort:'power',globeLayer:'snapshot',marker:'power',report:0,section:0,reportQ:'',dataTab:'sources',dataQ:'',book:0,sheet:0,costTab:'benchmarks',costLayer:'all',costQ:'',companyRegion:'all',companyQ:'',invest:'microsoft',compare:saved.compare||[],drawer:null,drawerHistory:[],tour:-1};
let globe=null,toastTimer=null,lastFocused=null,drawerReturn=null;
const save=()=>{saved.compare=state.compare;try{localStorage.setItem('compute-atlas-v3',JSON.stringify(saved))}catch{storageOK=false;};$('#shelf-count').textContent=saved.favorites.length};
const isSaved=id=>saved.favorites.includes(id);
const star=id=>`<button class="star-button ${isSaved(id)?'saved':''}" data-action="favorite" data-id="${esc(id)}" aria-label="${isSaved(id)?'Remove from':'Add to'} research shelf" aria-pressed="${isSaved(id)}">${isSaved(id)?'★':'☆'}</button>`;
const notice=(t,w=false)=>`<div class="notice ${w?'warning':''}">${t}</div>`;
const pagehead=(k,t,p,tools='')=>`<div class="page-heading"><div><div class="eyebrow">${k}</div><h1>${t}</h1><p>${p}</p></div><div class="page-tools">${tools}</div></div>`;
const metric=(value,label,note='',action='',id='')=>`<${action?'button':'div'} class="metric-card ${action?'interactive':''}" ${action?`data-action="${action}" data-id="${esc(id)}"`:''}><span class="metric-label">${label}</span><span class="metric-value">${value}</span><span class="metric-note">${note}</span></${action?'button':'div'}>`;
const raw=(x,title='Inspect source record')=>`<details class="raw-details"><summary>${esc(title)}</summary><pre>${esc(JSON.stringify(x,null,2))}</pre></details>`;
const kv=x=>`<div class="kv-grid">${Object.entries(x).map(([k,v])=>`<div class="key">${esc(k)}</div><div>${v==null?'<span class="muted">Not disclosed</span>':typeof v==='object'?esc(JSON.stringify(v)):esc(v)}</div>`).join('')}</div>`;
const color=s=>company(s?.primary_company)?.color||'#abc7d4';
const docStatus='ARCHIVE — Original attached report. Some fleet totals, power boundaries and valuation ratios are superseded. Use the correction register and facility dossiers for the app’s revised interpretation.';
function renderNav(){ $('#navigation').innerHTML=NAV.map(([id,label],i)=>`${i===8?'<div class="nav-divider"></div>':''}<button class="nav-button ${state.view===id?'active':''}" data-action="nav" data-id="${id}">${icon(id)}${label}</button>`).join('');save();$('#breadcrumb').textContent=NAV.find(x=>x[0]===state.view)?.[1]||'Your research shelf'; }
function navigate(view,opts={}){if(![...NAV.map(v=>v[0]),'watchlist','compare'].includes(view))view='overview';state.view=view;if(!opts.keepDrawer)closeDrawer();$('#sidebar').classList.remove('open');if(!opts.hash)history.replaceState(null,'','#'+view);render();window.scrollTo({top:0,behavior:'instant'});}
function render(){if(globe){globe.destroy();globe=null;}renderNav();const fn={catalog:()=>catalogView(),overview:overviewView,globe:globeView,facilities:facilitiesView,companies:companiesView,compare:compareView,contracts:contractsView,costs:costsView,investment:investmentView,reports:reportsView,data:dataView,stories:storiesView,watchlist:watchlistView}[state.view];$('#content').innerHTML=fn();if($('#globe-canvas'))globe=new AtlasGlobe($('#globe-canvas'));if(state.view==='costs'&&state.costTab==='scenario')updateScenario();if(state.view==='investment')updateInvestment();if(state.tour>=0)renderTour();}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2800);}
function filteredSites(){const f=state.filter;return D.sites.filter(s=>(f.company==='all'||s.company_ids.includes(f.company))&&(f.country==='all'||s.country===f.country)&&(f.review==='all'||s.review===f.review)&&(f.stage==='all'||(f.stage==='snapshot'&&s.snapshot)||(f.stage==='target'&&s.target)||(f.stage==='unknown'&&!s.snapshot&&!s.target))&&(!f.q||JSON.stringify([s.name,s.owner_label,s.location,s.hardware,s.facts]).toLowerCase().includes(f.q.toLowerCase()))).sort((a,b)=>state.sort==='name'?a.name.localeCompare(b.name):state.sort==='compute'?(b.snapshot?.h100e_k||0)-(a.snapshot?.h100e_k||0):state.sort==='target'?(b.target?.it_mw||0)-(a.target?.it_mw||0):(b.snapshot?.it_mw||0)-(a.snapshot?.it_mw||0));}
function filterControls(full=true){return `<div class="filterbar"><input id="site-query" type="search" value="${esc(state.filter.q)}" placeholder="Find a campus, place, owner or chip…" aria-label="Filter facilities"><select data-filter="company" aria-label="Filter company"><option value="all">All companies</option>${D.companies.map(c=>`<option value="${c.id}" ${state.filter.company===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><select data-filter="country" aria-label="Filter country"><option value="all">All geographies</option>${[...new Set(D.sites.map(s=>s.country))].sort().map(c=>`<option ${state.filter.country===c?'selected':''}>${esc(c)}</option>`).join('')}</select><select data-filter="review" aria-label="Filter evidence"><option value="all">All evidence</option>${[['reviewed-model','Reviewed site models'],['archive','Imported estimates'],['primary-noncomparable','Native-unit disclosures'],['contract-record','Contract records']].map(([v,l])=>`<option value="${v}" ${state.filter.review===v?'selected':''}>${l}</option>`).join('')}</select>${full?`<select data-filter="stage" aria-label="Filter status"><option value="all">All stages</option>${[['snapshot','Operating estimate'],['target','Has projected phase'],['unknown','AI MW unquantified']].map(([v,l])=>`<option value="${v}" ${state.filter.stage===v?'selected':''}>${l}</option>`).join('')}</select>`:''}<button class="btn small subtle" data-action="reset-filters">Reset</button></div>`;}
function globePanel(large=false){return `<div class="panel globe-panel ${large?'globe-large':''}"><canvas id="globe-canvas" role="img" aria-label="Interactive rotatable globe showing approximate facility locations. Use arrow keys to rotate, plus or minus to zoom. Facilities are also accessible in the linked list." tabindex="0"></canvas><div class="globe-top"><div class="globe-caption"><strong>${large?'A world of compute':'The physical layer'}</strong><span id="globe-live">Drag to rotate · scroll to zoom</span></div><div class="segmented"><button data-action="globe-layer" data-id="snapshot" class="${state.globeLayer==='snapshot'?'active':''}">Snapshot</button><button data-action="globe-layer" data-id="target" class="${state.globeLayer==='target'?'active':''}">Target phases</button></div></div><div class="globe-legend"><span><i class="legend-dot filled"></i>Modeled operating IT power</span><span><i class="legend-dot"></i>Projection or unquantified record</span><span>Numbered circles group nearby records</span></div><div class="globe-bottom"><div><div class="globe-controls"><button class="btn small" data-action="fly" data-id="americas">Americas</button><button class="btn small" data-action="fly" data-id="europe">Europe</button><button class="btn small" data-action="fly" data-id="asia">Asia</button></div><div class="globe-caption" style="margin-top:12px"><span class="mono" id="geo-position">Approximate locations · not a facility survey</span></div></div><div class="globe-controls"><button class="icon-button" data-action="globe-labels" aria-label="Toggle facility labels" title="Toggle labels">Aa</button><button class="icon-button" data-action="zoom" data-id="in" aria-label="Zoom in">+</button><button class="icon-button" data-action="zoom" data-id="out" aria-label="Zoom out">−</button><button class="icon-button" data-action="globe-fullscreen" aria-label="Toggle full screen globe" title="Full screen">⛶</button><button class="icon-button" data-action="globe-home" aria-label="Reset globe view" title="Reset globe">⌂</button></div></div></div>`;}
function companyFootprint(c){const ss=D.sites.filter(s=>s.primary_company===c.id&&s.snapshot);return {mw:ss.reduce((a,s)=>a+s.snapshot.it_mw,0),count:ss.length,reviewed:ss.filter(s=>s.review==='reviewed-model').length};}
function overviewView(){const sitesN=D.sites.length, mapped=D.sites.filter(s=>s.lat!=null).length, china=D.companies.filter(c=>c.region==='China').length, rows=A.legacy[0].current_sites.length+A.legacy[0].planned_sites.length;const ranked=D.companies.map(c=>({...c,fp:companyFootprint(c)})).filter(c=>c.fp.count).sort((a,b)=>b.fp.mw-a.fp.mw).slice(0,7),max=ranked[0].fp.mw;return `<div class="hero-top"><div><div class="eyebrow">COMPUTE, FROM THE GROUND UP</div><h1>Where compute<br>becomes capital.</h1></div><div class="hero-intro"><p>Explore the sites, the silicon, and the obligations behind AI infrastructure. Follow every headline down to its evidence.</p><button class="btn primary" data-action="tour-start">Take the five-stop tour <span>↗</span></button></div></div><div class="hero-layout">${globePanel()}<div class="story-stack"><button class="story-card" data-action="story" data-id="0"><span class="number">01 / CAPACITY IS NOT ONE NUMBER</span><span class="arrow">↗</span><h3>A gigawatt at the grid is not a gigawatt of compute.</h3><p>Follow New Carlisle from a headline power envelope to a dated IT-load estimate.</p></button><button class="story-card" data-action="story" data-id="1"><span class="number">02 / FOLLOW THE MONEY</span><span class="arrow">↗</span><h3>Who owns the building?<br>Who owns the chips?</h3><p>Helios connects a facility owner, GPU cloud and customer. They do not own the same asset.</p></button><button class="story-card" data-action="story" data-id="2"><span class="number">03 / A WIDER LANDSCAPE</span><span class="arrow">↗</span><h3>China belongs in the comparison. False precision does not.</h3><p>Explore ${china} Chinese companies, native disclosures and observed sites.</p></button></div></div><div class="metric-grid">${metric(fmt(sitesN),'Facility & project dossiers',`${mapped} approximate map anchors · not a global census`,'nav','facilities')}${metric(D.companies.length,'Companies across the value chain',`${china} Chinese companies · operators, customers & landlords`,'nav','companies')}${metric(D.sources.length,'Source records',`Report references plus site-level enrichment`,'nav','data')}${metric(rows,'Original facility-phase rows',`Every row retained, alongside corrected views`,'nav','reports')}</div><div class="grid-two"><section class="panel panel-pad"><div class="panel-head"><h2>A partial footprint, not a fleet ranking</h2><button class="text-button" data-action="nav" data-id="companies">Explore →</button></div><div class="bar-list">${ranked.map(c=>`<button class="bar-row" data-action="company" data-id="${c.id}"><span class="bar-name"><i class="dot" style="background:${c.color}"></i>${esc(c.name.replace('Alphabet / ','').replace('Amazon / ','').replace('xAI / SpaceXAI','xAI'))}</span><span class="bar-track"><span class="bar-fill" style="display:block;width:${c.fp.mw/max*100}%;background:${c.color}"></span></span><span class="bar-value">${gw(c.fp.mw)} GW</span></button>`).join('')}</div><p class="footnote">Sum of selected named-site snapshots by primary hardware-owner label. Mixed source vintages, incomplete coverage and mostly imported estimates. Neither available-for-rent capacity nor an installed company-fleet total. ${srefs(['S01','S02'])}</p></section><section class="panel panel-pad"><div class="panel-head"><h2>Start with an investment question</h2></div><div class="link-list"><button data-action="nav" data-id="contracts"><span>Which commitments overlap?</span><span>↗</span></button><button data-action="nav" data-id="costs"><span>What does one GW actually cost?</span><span>↗</span></button><button data-action="nav" data-id="investment"><span>What sits outside cash capex?</span><span>↗</span></button><button data-action="data-tab" data-id="corrections"><span>Which earlier conclusions changed?</span><span>↗</span></button></div><div class="notice compact warning">Evidence has a vintage. Some figures remain archival; modeled estimates are labeled. The original PDFs and workbook tables remain inspectable, including superseded calculations.</div></section></div>`;}
function globeView(){const list=filteredSites();return pagehead('THE PHYSICAL LAYER','Explore the compute globe.','Rotate the world, select a campus, then follow its power, hardware, costs and counterparties. Coordinates are approximate; unresolved locations stay in the directory.',`<button class="btn" data-action="nav" data-id="facilities">Open directory ↗</button>`)+filterControls(false)+`<div class="globe-layout">${globePanel(true)}<section class="panel globe-side"><div class="globe-side-header"><div class="panel-head"><h3>Matching facilities</h3><span class="pill">${list.length} records</span></div><p>Choose any record. Hollow markers do not imply zero compute.</p><div class="filter-inline"><label for="marker-metric">Marker size</label><select id="marker-metric" aria-label="Marker size metric"><option value="power" ${state.marker==='power'?'selected':''}>IT power</option><option value="compute" ${state.marker==='compute'?'selected':''}>H100-equivalents</option><option value="cost" ${state.marker==='cost'?'selected':''}>Modeled capex</option><option value="equal" ${state.marker==='equal'?'selected':''}>Equal size</option></select></div></div><div class="site-scroll" id="globe-list">${siteItems(list)}</div></section></div><p class="footnote">Sources and source dates are attached to each dossier. A target layer is a collection of phase estimates, not a forecast of signed aggregate supply. Drag / arrow keys rotate; + / − zoom. Nearby records cluster visually without merging their data.</p>`;}
function siteItems(ss){return ss.map(s=>`<button class="site-item" data-action="site" data-id="${s.id}"><i class="dot" style="background:${color(s)}"></i><div class="item-text"><strong>${esc(s.name)}</strong><span>${esc(s.owner_label)} · ${esc(s.country)}</span></div><div class="site-mw">${s[state.globeLayer]?.it_mw!=null?fmt(s[state.globeLayer].it_mw)+'<span>MW IT · model</span>':'—<span>not quantified</span>'}</div></button>`).join('')||'<div class="empty">No facilities match. Clear a filter to broaden the view.</div>';}
function siteTable(ss){return `<div class="table-wrap"><table><thead><tr><th></th><th><button data-action="sort" data-id="name">Facility / location ↕</button></th><th>Associated company</th><th class="number"><button data-action="sort" data-id="power">Snapshot IT MW ↕</button></th><th class="number"><button data-action="sort" data-id="compute">H100e (thousands) ↕</button></th><th class="number"><button data-action="sort" data-id="target">Projected IT MW ↕</button></th><th>Evidence / date</th><th></th></tr></thead><tbody>${ss.map(s=>`<tr class="clickable" data-action="site" data-id="${s.id}" tabindex="0" aria-label="Open ${esc(s.name)}"><td>${star(s.id)}</td><td><span class="cell-title">${esc(s.name)}</span><span class="cell-sub">${esc(s.location)}${s.lat==null?' · unmapped':''}</span></td><td><span class="cell-title" style="font-size:11px"><i class="dot" style="background:${color(s)}"></i>${esc(s.owner_label)}</span><span class="cell-sub">${esc(s.country)}</span></td><td class="number">${s.snapshot?fmt(s.snapshot.it_mw):'—'}</td><td class="number">${s.snapshot?fmt(s.snapshot.h100e_k,1):'—'}</td><td class="number">${s.target?fmt(s.target.it_mw):'—'}${s.target?.date?`<br><span class="cell-sub">${s.target.date}</span>`:''}</td><td>${rolePill(s)}<br><span class="cell-sub">${s.snapshot?.date||'See source'}</span></td><td>↗</td></tr>`).join('')}</tbody></table></div>`;}
function siteCards(ss){return `<div class="card-grid">${ss.map(s=>`<article class="facility-card"><div class="flex">${rolePill(s)}<span class="spacer"></span>${star(s.id)}</div><button class="title-link" data-action="site" data-id="${s.id}"><h3>${esc(s.name)} ↗</h3></button><div class="cell-sub">${esc(s.owner_label)} · ${esc(s.location)}</div><div class="mini-stats"><div><strong>${s.snapshot?fmt(s.snapshot.it_mw):'—'}</strong><span>Snapshot IT MW</span></div><div><strong>${s.target?fmt(s.target.it_mw):'—'}</strong><span>Projected IT MW</span></div></div><div class="tag-row">${phasePill(s)}${srefs(s.sources.slice(0,2))}</div></article>`).join('')}</div>`;}
function siteScatter(ss){const ps=ss.filter(s=>s.snapshot?.it_mw>0&&s.snapshot?.h100e_k!=null),w=980,h=510,left=83,right=40,top=38,bottom=70,xmax=Math.ceil(Math.max(100,...ps.map(s=>s.snapshot.it_mw))/200)*200,ymax=Math.ceil(Math.max(100,...ps.map(s=>s.snapshot.h100e_k))/200)*200;const px=n=>left+n/xmax*(w-left-right),py=n=>h-bottom-n/ymax*(h-top-bottom);return `<section class="panel panel-pad"><div class="panel-head"><h2>Power is not the same as useful throughput.</h2><span class="pill">Click any facility</span></div><p style="font-size:11px">Selected facility snapshots only. Vertical separation at similar IT power reveals different theoretical compute intensity; it does not measure real-world application efficiency.</p><svg class="chart-svg" viewBox="0 0 ${w} ${h}" role="img" aria-label="Scatter plot of facility IT megawatts versus theoretical H100 equivalents">${Array.from({length:6},(_,i)=>{let x=i*xmax/5,y=i*ymax/5;return `<path d="M${px(x)} ${top}V${h-bottom}M${left} ${py(y)}H${w-right}" stroke="#2c4051" stroke-width=".7"/><text x="${px(x)}" y="${h-bottom+24}" text-anchor="middle" fill="#a1b4c5" font-size="10">${fmt(x)}</text><text x="${left-13}" y="${py(y)+4}" text-anchor="end" fill="#a1b4c5" font-size="10">${fmt(y)}</text>`}).join('')}<text x="${w/2}" y="${h-14}" text-anchor="middle" fill="#b4cbd4" font-size="12">Snapshot IT power (MW)</text><text x="22" y="${h/2}" transform="rotate(-90 22 ${h/2})" text-anchor="middle" fill="#b4cbd4" font-size="12">Theoretical H100e (thousands)</text>${ps.map(s=>`<g class="scatter-point" data-action="site" data-id="${s.id}" tabindex="0" role="button" aria-label="${esc(s.name)}, ${fmt(s.snapshot.it_mw)} MW, ${fmt(s.snapshot.h100e_k)} thousand H100 equivalents"><circle cx="${px(s.snapshot.it_mw)}" cy="${py(s.snapshot.h100e_k)}" r="${s.review==='reviewed-model'?7:5}" fill="${color(s)}" fill-opacity="${s.review==='reviewed-model'?'.95':'.53'}" stroke="${color(s)}" stroke-width="1.4"/><title>${esc(s.name)} · ${esc(s.owner_label)}
${fmt(s.snapshot.it_mw)} MW IT / ${fmt(s.snapshot.h100e_k)}k H100e
${esc(s.review)}</title>${['Zhangbei','Horinger','New Carlisle','Colossus 2'].includes(s.name)?`<text x="${px(s.snapshot.it_mw)+11}" y="${py(s.snapshot.h100e_k)-8}" fill="#c9dce2" font-size="10">${esc(s.name)}</text>`:''}</g>`).join('')}</svg><div class="tag-row">${[...new Set(ps.map(s=>s.primary_company))].map(company).filter(Boolean).map(c=>`<button class="pill" data-action="filter-company" data-id="${c.id}"><i class="dot" style="background:${c.color};margin-right:2px"></i>${esc(c.name)}</button>`).join('')}</div><p class="footnote">${ps.length} plotted facilities; ${ss.length-ps.length} matching records lack comparable snapshot coordinates and are not plotted. Larger, opaque dots identify reviewed site models; other points are imported estimates. ${srefs(['S01','S02','N05','N06'])}</p></section>`;}
function facilitiesView(){const ss=filteredSites();return pagehead('FACILITY DIRECTORY','Every site has a story.','All original site-phase rows are preserved. Dossiers combine phase records without hiding revisions, role ambiguity or missing power and hardware disclosures.',`<button class="btn" data-action="export-sites">Export filtered CSV ↓</button><button class="btn primary" data-action="nav" data-id="globe">Explore on globe ↗</button>`)+filterControls()+`<div class="panel-head"><div class="statline"><span><b>${ss.length}</b> dossiers</span><span><b>${ss.filter(s=>s.snapshot).length}</b> with an operating estimate</span><span><b>${ss.filter(s=>s.target).length}</b> with a target phase</span><span><b>${ss.filter(s=>s.lat==null).length}</b> not geolocated</span></div><div class="segmented"><button data-action="site-layout" data-id="table" class="${state.layout==='table'?'active':''}">Table</button><button data-action="site-layout" data-id="cards" class="${state.layout==='cards'?'active':''}">Cards</button><button data-action="site-layout" data-id="chart" class="${state.layout==='chart'?'active':''}">Scatter</button></div></div>${ss.length?(state.layout==='table'?siteTable(ss):state.layout==='chart'?siteScatter(ss):siteCards(ss)):'<div class="empty"><h3>No matching facilities</h3><p>Try a broader region or remove the evidence filter.</p><button class="btn" data-action="reset-filters">Clear filters</button></div>'}<p class="footnote">H100e = theoretical dense-equivalent eight-bit throughput in the underlying model, not identical workload performance. “Snapshot” does not mean all capacity is commercially available. Empty values mean not established, not zero.</p>`;}
function companiesView(){const cs=D.companies.filter(c=>(state.companyRegion==='all'||c.region===state.companyRegion)&&(!state.companyQ||JSON.stringify([c.name,c.role,c.ticker]).toLowerCase().includes(state.companyQ.toLowerCase())));return pagehead('COMPANY UNIVERSE','One landscape. Different businesses.','Cloud platforms, private model companies, telecom operators and landlords have different economics. Compare their evidence and obligations without inventing a uniform fleet total.')+`<div class="filterbar"><input type="search" id="company-query" value="${esc(state.companyQ)}" placeholder="Find a company, ticker or role…" aria-label="Filter companies"><div class="segmented">${[['all','All'],['US','US'],['China','China'],['Europe','Europe']].map(([v,l])=>`<button data-action="company-region" data-id="${v}" class="${state.companyRegion===v?'active':''}">${l}</button>`).join('')}</div><span class="count">${cs.length} companies</span></div><div class="card-grid">${cs.map(c=>{const n=D.sites.filter(s=>s.company_ids.includes(c.id)).length;return `<article class="company-card"><div class="company-card-head"><span class="company-token" style="color:${c.color};border-color:${c.color}55;background:${c.color}12">${esc(c.name.split(' / ')[0].slice(0,2).toUpperCase())}</span><label class="compare-check"><input type="checkbox" data-compare="${c.id}" ${state.compare.includes(c.id)?'checked':''}>Compare</label></div><button class="title-link" data-action="company" data-id="${c.id}"><h3>${esc(c.name)} ↗</h3></button><div class="tag-row" style="margin-bottom:16px"><span class="pill">${esc(c.region)}</span><span class="pill">${esc(c.role)}</span></div><p>${esc(c.headline)}</p><div class="company-card-footer"><span>${n} linked ${n===1?'dossier':'dossiers'} · ${c.sources.length} references</span><span class="mono">${esc(c.ticker.split(' / ')[0])}</span></div></article>`}).join('')}</div>${compareDock()}`;}
function compareDock(){return state.compare.length?`<div class="compare-dock"><span class="small-title">${state.compare.length} of 4 selected</span><span class="muted" style="font-size:11px">${state.compare.map(id=>esc(company(id)?.name.split(' / ')[0])).join(' · ')}</span><button class="btn primary" data-action="nav" data-id="compare">Compare companies →</button><button class="text-button" data-action="clear-compare">Clear</button></div>`:'';}
function compareView(){const cs=state.compare.map(company).filter(Boolean);if(!cs.length)return pagehead('SIDE BY SIDE','Choose your comparison.','Select up to four companies in the company universe.')+`<button class="btn primary" data-action="nav" data-id="companies">Choose companies →</button>`;const rows=[['Business role',c=>esc(c.role)],['Region / identifier',c=>`${esc(c.region)}<br><span class="mono">${esc(c.ticker)}</span>`],['Named linked dossiers',c=>`<button class="text-button" data-action="filter-company" data-id="${c.id}">${D.sites.filter(s=>s.company_ids.includes(c.id)).length} facilities / projects ↗</button>`],['Whole-company installed IT GW',c=>'Not established by this collection'],['Selected primary-owner site snapshot',c=>{const f=companyFootprint(c);return f.count?`${gw(f.mw)} GW from ${f.count} named sites<br><span class="cell-sub">Not a fleet total; ${f.reviewed} reviewed site models.</span>`:'Not quantified; not zero'}],['Capital-return question',c=>`<p>${esc(c.thesis)}</p>`],['Principal interpretation risk',c=>`<p>${esc(c.risk)}</p>`],['Cash capex / operating cash flow',c=>c.commitment?`${money(c.commitment.capex_b,2)} / ${money(c.commitment.ocf_b,2)}<br><span class="cell-sub">${esc(c.commitment.period)}; imported, mixed periods</span>${srefs(c.commitment.sources)}`:'Not populated from the supplied workbook'],['Uncommenced lease commitments',c=>c.commitment?`${money(c.commitment.uncommenced_leases_b,2)}<br><span class="cell-sub">No automatic addition to other commitments</span>${srefs(c.commitment.sources)}`:'Not established here'],['Historical market capitalization',c=>c.stock?`${money(c.stock.market_cap_b,1)}<br><span class="pill archive">2026-08-31 · unverified archive</span>`:'Not populated / private'],['Monitoring priorities',c=>`<p>${esc(c.watch)}</p>`],['Evidence',c=>srefs(c.sources)]];return pagehead('SIDE BY SIDE','Compare the business, not just the watts.','Different reporting periods and ownership boundaries remain explicit. No complete-fleet or market-cap-per-fleet-GW ranking is inferred.',`<button class="btn" data-action="nav" data-id="companies">Edit comparison</button>`)+notice('Selected-site snapshots are incomplete and unequally covered. Their relative size is not a reliable ranking of total corporate compute.',true)+`<div class="table-wrap"><table class="compare-table"><thead><tr><th>Dimension</th>${cs.map(c=>`<th><button class="text-button" data-action="company" data-id="${c.id}">${esc(c.name)} ↗</button></th>`).join('')}</tr></thead><tbody>${rows.map(([label,fn])=>`<tr><td>${label}</td>${cs.map(c=>`<td>${fn(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function networkSVG(){const nodes=[['hut8',50,80,'Hut 8','Facility'],['galaxy',50,220,'Galaxy','Facility'],['iren',50,360,'IREN','Hardware + service'],['fluidstack',345,80,'Fluidstack','Tenant'],['coreweave',345,220,'CoreWeave','GPU cloud'],['microsoft',345,360,'Microsoft','Cloud / buyer'],['google',640,80,'Google','Backstop'],['openai',640,220,'OpenAI','Compute customer'],['anthropic',640,360,'Anthropic','Compute customer']];return `<svg class="network" viewBox="0 0 890 450" role="img" aria-label="Illustrative relationships among facility providers, cloud operators and customers; not an exhaustive or additive capacity network"><text x="50" y="30" fill="#8daabb" font-size="10" letter-spacing="1.5">ASSET / SUPPLY LAYER</text><text x="345" y="30" fill="#8daabb" font-size="10" letter-spacing="1.5">OPERATOR / INTERMEDIARY</text><text x="640" y="30" fill="#8daabb" font-size="10" letter-spacing="1.5">DEMAND / CREDIT SUPPORT</text>${[[245,110,345,110,'245 MW lease'],[245,250,345,250,'526 MW critical IT'],[245,390,345,390,'200 MW service'],[540,110,640,110,'Backstop'],[540,250,640,250,'Customer relation*'],[540,390,640,390,'Demand commitment']].map(([x,y,xx,yy,l])=>`<path class="edge" d="M${x} ${y}C${(x+xx)/2} ${y},${(x+xx)/2} ${yy},${xx} ${yy}"/><text class="edge-label" x="${(x+xx)/2}" y="${y-13}" text-anchor="middle">${l}</text>`).join('')}${nodes.map(([id,x,y,n,r])=>`<g class="node" data-action="company" data-id="${id}" tabindex="0" role="button" aria-label="Open ${n}"><rect x="${x}" y="${y}" width="195" height="60" rx="7" fill="#192b39" stroke="#3a5260"/><circle cx="${x+16}" cy="${y+21}" r="3" fill="${company(id)?.color||'#8de0c2'}"/><text x="${x+28}" y="${y+25}" fill="#dcebed" font-size="12">${n}</text><text x="${x+16}" y="${y+45}" fill="#91a8b6" font-size="9">${r}</text></g>`).join('')}</svg>`;}
function contractsView(){return pagehead('THE CONTRACTING CHAIN','Follow the same megawatt through the stack.','A campus can appear in the landlord’s lease, the cloud provider’s service purchase and the model company’s demand agreement. Those are relationships—not three additive pools of compute.',`<button class="btn" data-action="export-section" data-id="contracts">Export contracts JSON ↓</button>`)+`<section class="panel panel-pad"><div class="panel-head"><h2>Selected relationships</h2><span class="pill">Click any company</span></div>${networkSVG()}<p class="footnote">Schematic, not an exhaustive ownership or payment map. The CoreWeave–OpenAI customer connection does not establish an OpenAI tenancy at Helios; that site attribution is speculative. Power figures are contract boundaries, not active fleet totals. ${srefs(['S17','S19','S38','S42','S49'])}</p></section><div class="section-gap">${notice('Programs, supply contracts, internal project targets and company-wide contracted power remain separate. None of the rows below should be mechanically summed.',true)}</div><div class="table-wrap"><table><thead><tr><th>Vendor / counterparty</th><th>Capacity qualifier</th><th class="number">Referenced GW</th><th class="number">Nominal value</th><th>Timing / overlap</th><th>Sources</th></tr></thead><tbody>${D.contracts.map(c=>`<tr class="clickable" data-action="contract" data-id="${c.id}" tabindex="0"><td><span class="cell-title">${esc(c.vendor)}</span><span class="cell-sub">${esc(c.counterparty)}</span></td><td>${esc(c.status)}<br><span class="cell-sub">${esc(c.capacity_type)}</span></td><td class="number">${c.capacity_gw==null?'Not disclosed':fmt(c.capacity_gw,3)}</td><td class="number">${c.contract_value_b==null?'Not disclosed':money(c.contract_value_b)}<br><span class="cell-sub">${c.term_years?fmt(c.term_years)+' years':'Term not disclosed'}</span></td><td>${esc(c.near_term)}<br><span class="cell-sub">${esc(c.overlap_note)}</span></td><td>${srefs(c.sources)} ↗</td></tr>`).join('')}</tbody></table></div><div class="grid-two section-gap"><section class="panel panel-pad"><h3>What qualifies as signed?</h3><p style="font-size:12px">A contract record establishes only the quantity, service, term and conditions that the underlying disclosure actually specifies. A construction target, unexercised option or utility interconnection request is not automatically signed accelerator supply.</p><button class="text-button" data-action="method">Open the interpretation guide →</button></section><section class="panel panel-pad"><h3>Reconcile entities before capacity</h3><p style="font-size:12px">The relevant questions are: who owns the equipment, who owns the property, who sells the service, and who pays or guarantees the bill? Facility dossiers preserve these roles wherever the cited record supports them.</p><button class="text-button" data-action="site" data-id="${D.sites.find(s=>s.name==='Helios').id}">Inspect the Helios chain →</button></section></div>`;}
function costsView(){return pagehead('ECONOMICS & NORMALIZATION','A gigawatt has more than one price.','Separate infrastructure, equipment, leases and managed services. Then test the cost of useful compute against equipment life, utilization, electricity and financing assumptions.')+`<div class="tabs">${[['benchmarks','Observed cost layers'],['scenario','Interactive economics lab'],['hardware','Hardware normalization'],['company','Per-company evidence']].map(([v,l])=>`<button data-action="cost-tab" data-id="${v}" class="${state.costTab===v?'active':''}">${l}</button>`).join('')}</div>`+({benchmarks:benchmarksView,scenario:scenarioView,hardware:hardwareView,company:companyCostsView}[state.costTab])();}
function benchmarksView(){const layers=[...new Set(D.costs.map(c=>c.layer))],cs=D.costs.filter(c=>(state.costLayer==='all'||c.layer===state.costLayer)&&(!state.costQ||JSON.stringify(c).toLowerCase().includes(state.costQ.toLowerCase())));return notice('Values below retain their original cost layer. A lease’s lifetime face value is not capital expenditure; annualizing it does not make it a financed full-stack TCO estimate.')+`<div class="filterbar"><input type="search" id="cost-query" value="${esc(state.costQ)}" placeholder="Search a company, counterparty or cost…" aria-label="Search cost benchmarks"><select id="cost-layer" aria-label="Cost layer"><option value="all">All cost layers — not additive</option>${layers.map(l=>`<option ${state.costLayer===l?'selected':''}>${esc(l)}</option>`).join('')}</select><span class="count">${cs.length} benchmarks</span></div><div class="table-wrap"><table><thead><tr><th>Benchmark / cost layer</th><th class="number">Power MW</th><th class="number">Original nominal $B/GW</th><th class="number">Original $B/GW-year</th><th>Included?</th><th>Evidence</th></tr></thead><tbody>${cs.map(c=>`<tr class="clickable" data-action="cost" data-id="${c.id}" tabindex="0"><td><span class="cell-title">${esc(c.benchmark)}</span><span class="cell-sub">${esc(c.layer)}</span></td><td class="number">${c.capacity_mw==null?'—':fmt(c.capacity_mw)}</td><td class="number">${c.nominal_b_per_gw==null?'—':fmt(c.nominal_b_per_gw,2)}</td><td class="number">${c.annual_b_per_gw==null?'—':fmt(c.annual_b_per_gw,2)}</td><td><span class="cell-sub">Power: ${esc(c.power_included)}<br>Hardware: ${esc(c.hardware_included)}</span></td><td>${srefs(c.sources)}<br><span class="cell-sub">Imported benchmark ↗</span></td></tr>`).join('')}</tbody></table></div><p class="footnote">The table exposes original audit-model ratios, not a new all-in price survey. Open each row for the numerator, term, capacity denominator and scope caveat. Some cross-announcement ratios are not commercially comparable prices.</p>`;}
const scenario={capex:37.883,share:69,itlife:5,faclife:14,util:71,pue:1.18,power:.08,rate:8,opex:.5,eff:1.378106};
function control(id,label,min,max,step,value,unit){return `<div class="control"><label for="s-${id}"><span>${label}</span><output id="o-${id}">${value}${unit}</output></label><input type="range" id="s-${id}" data-scenario="${id}" min="${min}" max="${max}" step="${step}" value="${value}" aria-label="${label}"></div>`;}
function scenarioView(){return `<div class="cost-layout"><section class="panel panel-pad"><div class="panel-head"><h2>One IT GW. Your assumptions.</h2><button class="text-button" data-action="reset-scenario">Reset</button></div><p style="font-size:11px">An explicit annuity-cost model. Defaults are scenario assumptions, not any company’s actual procurement or financing terms. The historical $37.883B reference comes from the source report. ${srefs('S03')}</p><div class="controls-grid">${control('capex','Total installed capex ($B)',10,80,.1,scenario.capex,'B')}${control('share','Equipment share of capex',40,90,1,scenario.share,'%')}${control('itlife','IT equipment life',2,8,1,scenario.itlife,' yr')}${control('faclife','Facility asset life',10,30,1,scenario.faclife,' yr')}${control('util','Productive utilization',20,95,1,scenario.util,'%')}${control('pue','PUE',1.05,1.6,.01,scenario.pue,'×')}${control('power','Electricity ($/kWh)',.02,.2,.005,scenario.power,'')}${control('rate','Capital recovery rate',0,18,.5,scenario.rate,'%')}${control('opex','Other annual opex ($B)',0,2,.05,scenario.opex,'B')}${control('eff','H100e per IT GW (millions)',.3,2.5,.025,scenario.eff,'M')}</div><div class="equation">CRF(r,n) = r ÷ [1 − (1+r)<sup>−n</sup>]<br>Capital charge = equipment × CRF + facility × CRF<br>Electricity = 1M kW × 8,760h × PUE × $/kWh<br>Unit cost = annual cost ÷ (H100e × 8,760h × utilization)</div><p class="footnote">Power is conservatively charged at full design IT load for the whole year, independently of productive utilization. No taxes, working capital, salvage value, demand charges or actual chip degradation are modeled. Recovery rate is a scenario input, not a quoted cost of capital.</p><button class="btn" data-action="export-scenario">Export assumptions & results ↓</button></section><div><section class="panel panel-pad"><div class="result-label">MODELED COST PER PRODUCTIVE H100e-HOUR</div><div class="big-number" id="scenario-unit">—</div><div id="scenario-stats"></div><div class="stacked-bar" id="scenario-stack"></div><div class="stacked-legend"><span><i class="dot" style="background:#8de0c2"></i>Capital recovery</span><span><i class="dot" style="background:#88b4ed"></i>Electricity</span><span><i class="dot" style="background:#e4bd7a"></i>Other opex</span></div></section><section class="panel panel-pad section-gap"><div class="panel-head"><h3>The utilization × refresh frontier</h3><span class="pill">Click a cell</span></div><p class="footnote" style="margin-top:0;margin-bottom:16px">Cost per productive H100e-hour. Columns: productive utilization. Rows: equipment life. All other assumptions are held fixed.</p><div class="heatmap" id="scenario-heatmap"></div></section><div class="notice compact warning">H100e is a theoretical throughput convention. It is not a rentable H100 instance, a standardized token price or equal real-world model performance.</div></div></div>`;}
function calculateScenario(p=scenario){let crf=(r,n)=>r===0?1/n:r/(1-Math.pow(1+r,-n));let eq=p.capex*p.share/100,fac=p.capex-eq,capital=eq*crf(p.rate/100,p.itlife)+fac*crf(p.rate/100,p.faclife),electricity=.00876*p.pue*p.power*1000,total=capital+electricity+p.opex,unit=total*1e9/(p.eff*1e6*8760*p.util/100);return{capital,electricity,other:p.opex,total,unit,equipment_capex:eq,facility_capex:fac};}
function updateScenario(){if(!$('#scenario-unit'))return;const r=calculateScenario();Object.entries(scenario).forEach(([k,v])=>{const o=$('#o-'+k);if(o)o.textContent=k==='power'?'$'+fmt(v,3):k==='pue'?fmt(v,2)+'×':k==='eff'?fmt(v,3)+'M':['util','share','rate'].includes(k)?fmt(v,1)+'%':['itlife','faclife'].includes(k)?v+' yr':money(v,2);});$('#scenario-unit').innerHTML='$'+fmt(r.unit,2)+' <small>/ productive H100e-hour</small>';$('#scenario-stats').innerHTML=`<div class="dashboard-line"><span>Annualized total cost / IT-GW-year</span><strong>${money(r.total,2)}</strong></div><div class="dashboard-line"><span>Annual capital recovery</span><strong>${money(r.capital,2)}</strong></div><div class="dashboard-line"><span>Annual electricity cost</span><strong>${money(r.electricity,2)}</strong></div><div class="dashboard-line"><span>Equipment / facility capex</span><strong>${money(r.equipment_capex,1)} / ${money(r.facility_capex,1)}</strong></div>`;$('#scenario-stack').innerHTML=[['capital','#8de0c2'],['electricity','#88b4ed'],['other','#e4bd7a']].map(([k,c])=>`<div title="${k}: ${money(r[k],2)}" style="width:${r[k]/r.total*100}%;background:${c}"></div>`).join('');const us=[40,55,70,85,95],ls=[2,3,4,5,7],vals=ls.flatMap(l=>us.map(u=>calculateScenario({...scenario,itlife:l,util:u}).unit)),lo=Math.min(...vals),hi=Math.max(...vals);$('#scenario-heatmap').innerHTML='<div class="heat-label">Life ↓</div>'+us.map(u=>`<div class="heat-label">${u}%</div>`).join('')+ls.map(l=>`<div class="heat-label">${l} years</div>${us.map(u=>{const v=calculateScenario({...scenario,itlife:l,util:u}).unit,t=(v-lo)/(hi-lo);return `<button data-action="heat" data-life="${l}" data-util="${u}" class="${scenario.itlife===l&&scenario.util===u?'selected':''}" style="background:hsl(${165-t*127} 25% ${23+t*7}%)" title="${l}-year equipment life, ${u}% utilization">$${fmt(v,2)}</button>`}).join('')}`).join('');}
function hardwareView(){return notice('Only like-for-like precision and power boundaries belong in the same comparison. B100’s system envelope is explicitly approximate; memory, interconnect, software and workload efficiency are not captured by one H100e scalar.',true)+`<div class="card-grid">${D.normalization.map((n,i)=>`<article class="chip-card"><h3>${esc(n.platform)}</h3><div class="chip-value">${fmt(n.h100e_per_it_gw/1e6,3)}M</div><div class="cell-sub">Theoretical H100e per IT GW</div><div class="dashboard-line"><span>Platform power</span><strong>${fmt(n.system_kw,1)} kW</strong></div><div class="dashboard-line"><span>Physical GPUs per platform</span><strong>${n.physical_gpu}</strong></div><div class="dashboard-line"><span>External IT overhead assumption</span><strong>${fmt(n.overhead_pct*100)}%</strong></div><div class="dashboard-line"><span>Physical GPUs per IT GW</span><strong>${fmt(n.physical_per_it_gw)}</strong></div><p style="margin-top:14px">${esc(n.notes)}</p>${srefs(n.sources)}<button class="text-button" style="display:block;margin-top:15px" data-action="hardware" data-id="${i}">Inspect formula and original inputs →</button></article>`).join('')}</div><section class="panel panel-pad section-gap"><h3>The conversion bridge</h3><div class="equation">IT kW per accelerator = platform kW ÷ accelerator count × (1 + external IT overhead)<br>Physical accelerators per IT GW = 1,000,000 kW ÷ IT kW per accelerator<br>H100e per IT GW = physical count × dense-equivalent eight-bit throughput ratio<br>H100e per facility GW = H100e per IT GW ÷ PUE</div><p class="footnote">The H200 row inherits an H100-like system envelope in the original model; it is a simplifying power/throughput comparison, not a claim that all H200 systems draw identical power. The reviewed China facility records use Epoch’s own H20 / Ascend site model, not an invented universal bridge.</p></section>`;}
function companyCostsView(){const cc=[{id:'amazon',label:'Indiana campus investment',value:'$6.25B / disclosed GW',kind:'Campus infrastructure; IT boundary unestablished',math:'$15B ÷ 2.4 GW',note:'No PUE-based IT normalization is applied. Not an all-in GPU fleet cost.',sources:['S26']},{id:'microsoft',label:'IREN / Dell equipment',value:'$29.0B / IT GW',kind:'GPU-related equipment capex',math:'$5.8B ÷ 0.2 GW IT',note:'Equipment procurement, not a complete greenfield data-center cost.',sources:['S17']},{id:'microsoft',label:'IREN managed service',value:'$9.70B / IT-GW-year',kind:'Nominal multiyear compute service',math:'$9.7B ÷ 0.2 GW IT ÷ 5 years',note:'Customer service consideration, not annual provider operating cost.',sources:['S17']},{id:'google',label:'River Bend construction',value:'$9–11B / IT GW',kind:'Facility construction estimate',math:'Disclosed $9–11M per MW IT',note:'Hut 8 / Fluidstack project with Google-linked payment support; not Google-owned capex.',sources:['S49']},{id:'google',label:'River Bend lease',value:'$1.90B / IT-GW-year',kind:'Nominal facility lease',math:'$7B ÷ 0.245 GW IT ÷ 15 years',note:'Do not add lease face value to construction capex as independent economic costs.',sources:['S49']},{id:'meta',label:'Hyperion JV versus wider target',value:'No clean matched-scope ratio',kind:'Long-lived JV assets vs multi-stage program',math:'Original $27B ÷ 5 GW = $5.4B/GW',note:'Arithmetic is preserved, but scope and phase matching are unproven; not an all-in cost.',sources:['S28','S29']},{id:'oracle',label:'Cross-announcement service ratio',value:'Not a comparable unit price',kind:'Program and contract values across announcements',math:'Original $300B / 5.5 GW / 5 years',note:'Different denominators and possible overlap prevent treatment as an observed standardized service price.',sources:['S33','S34']},{id:'coreweave',label:'Counterparty lease benchmarks',value:'Multiple distinct layers',kind:'Facility leases, retrofits and GPU financing',math:'Open the benchmark register for each matched term and MW boundary.',note:'No full-stack per-GW company price is established by a mixed portfolio of leases.',sources:['S37','S39','S42']},{id:'tesla',label:'Compute-only procurement cost',value:'Not disclosed in this dataset',kind:'No clean AI-only numerator and facility denominator',math:'No calculation applied.',note:'Company-wide capex and model-estimated cluster power are not a matched pair.',sources:['S47']}];return notice('These are usable cost observations or explicit reasons not to compute a ratio. They replace the earlier presentation of a common replacement cost as each company’s actual price.')+`<div class="card-grid">${cc.map(c=>`<article class="panel panel-pad"><div class="flex"><span class="dot" style="background:${company(c.id).color}"></span><button class="text-button" data-action="company" data-id="${c.id}">${esc(company(c.id).name)}</button></div><h3 style="margin:17px 0 12px">${c.label}</h3><div style="font:22px Georgia,serif;line-height:1.35;color:#d8e9e5;margin-bottom:12px">${c.value}</div><span class="pill">${c.kind}</span><div class="equation">${c.math}</div><p style="font-size:11px">${c.note}</p>${srefs(c.sources)}</article>`).join('')}</div><section class="panel panel-pad section-gap"><h3>China: preserve the missing denominator</h3><p style="font-size:12px">This source set does not establish company-specific, matched-scope all-in prices per AI IT GW for the Chinese comparison group. Site-level modeled replacement costs are visible in Zhangbei and Horinger dossiers, but they are not actual procurement prices. ${srefs(['N05','N06'])}</p><button class="btn" data-action="company-region-link" data-id="China">Explore Chinese company evidence →</button></section>${raw(D.direct_costs,'All 11 original per-company cost-evidence records — archival, including superseded ratios')}`;}
function investmentView(){const c=company(state.invest)||company('microsoft'),f=c.commitment,st=c.stock;return pagehead('INVESTMENT LENS','Watts are an input. Cash returns are the question.','Keep the asset, funding and monetization layers separate. This is a framework for diligence, not a live-price recommendation or an automated target-price model.')+notice('Market prices and market capitalizations below are the original report’s unverified 31 August 2026 snapshot. They are not refreshed quotes. Financial footnotes are imported evidence with differing periods; open the source before relying on them.',true)+`<div class="filterbar"><select id="invest-company" aria-label="Investment company">${D.companies.map(x=>`<option value="${x.id}" ${c.id===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select><button class="btn" data-action="company" data-id="${c.id}">Company dossier ↗</button><button class="btn" data-action="filter-company" data-id="${c.id}">Linked facilities ↗</button></div><div class="grid-two"><section class="invest-card"><div class="flex"><span class="company-token" style="color:${c.color};border-color:${c.color}66">${esc(c.name.slice(0,2).toUpperCase())}</span><div><h2 style="margin:0 0 5px">${esc(c.name)}</h2><span class="cell-sub">${esc(c.ticker)} · ${esc(c.role)}</span></div></div><p class="thesis-text">${esc(c.headline)}</p><p style="font-size:12px">${esc(c.thesis)}</p><div class="dossier-hero"><div class="small-title">THE UNDERWRITING RISK</div><p>${esc(c.risk)}</p></div><h3>What to monitor</h3><p style="font-size:12px">${esc(c.watch)}</p>${srefs(c.sources)}<div class="invest-metrics"><div><span>Historical equity market value</span><strong>${st?money(st.market_cap_b,1):'Not populated'}</strong><span>${st?'31 Aug 2026 · original, unverified':'Private or no verified quote in this dataset'}</span></div><div><span>Historical share price</span><strong>${st?'$'+fmt(st.share_price,2):'Not populated'}</strong><span>${st?'USD · not a live quote':'No live price inference'}</span></div></div></section><section class="panel panel-pad"><div class="panel-head"><h2>Funding and obligations</h2><span class="pill archive">${esc(f?.period||'Not populated')}</span></div>${f?`<div class="dashboard-line"><span>Cash capex</span><strong>${money(f.capex_b,2)}</strong></div><div class="dashboard-line"><span>Operating cash flow</span><strong>${money(f.ocf_b,2)}</strong></div><div class="dashboard-line"><span>Cash capex / operating cash flow</span><strong>${f.ocf_b?fmt(f.capex_b/f.ocf_b,2)+'×':'Not available'}</strong></div><div class="dashboard-line"><span>Uncommenced leases (see scope)</span><strong>${money(f.uncommenced_leases_b,2)}</strong></div><div class="dashboard-line"><span>Purchase / contractual commitments</span><strong>${money(f.purchase_or_contract_b,2)}</strong></div><div class="dashboard-line"><span>Net property, plant & equipment</span><strong>${money(f.net_ppe_b,2)}</strong></div><div class="dashboard-line"><span>Construction in progress</span><strong>${money(f.cip_b,2)}</strong></div><div class="dashboard-line"><span>Reported debt in source model</span><strong>${money(f.debt_b,2)}</strong></div><div class="dashboard-line"><span>RPO / backlog (definitions vary)</span><strong>${money(f.rpo_b,2)}</strong></div><p class="footnote">${esc(f.notes)} ${srefs(f.sources)}</p><button class="text-button" style="margin-top:15px" data-action="footnote" data-id="${c.id}">Open the entire footnote record →</button>`:`<div class="empty"><h3>No matched financial record</h3><p>Absence here does not mean the company has no compute or obligations. The app does not fabricate missing financials.</p></div>${(c.facts||[]).map(factHTML).join('')}`}</section></div><section class="panel panel-pad section-gap"><div class="panel-head"><h2>Valuation sensitivity, without a false fleet denominator</h2><span class="pill">User assumptions</span></div><div class="grid-two"><div><div class="invest-inputs"><label>Equity market value ($B)<input type="number" min="0.01" step="1" id="v-market" value="${st?st.market_cap_b.toFixed(1):100}" aria-label="Assumed equity market value"></label><label>Incremental IT capacity (GW)<input type="number" min="0.01" max="100" step=".1" id="v-gw" value="1" aria-label="Assumed incremental IT GW"></label><label>Installed capex per IT GW ($B)<input type="number" min=".01" step=".1" id="v-capex" value="37.883" aria-label="Assumed installed capex per GW"></label><label>Annual free cash flow after refresh ($B/GW)<input type="number" min="-100" max="100" step=".1" id="v-fcf" value="2" aria-label="Assumed annual free cash flow per GW"></label><label>Discount rate (%)<input type="number" min=".1" max="100" step=".5" id="v-rate" value="10" aria-label="Discount rate"></label><label>Duration (years)<input type="number" min="1" max="50" step="1" id="v-years" value="10" aria-label="Duration in years"></label></div><p class="footnote">The FCF assumption must already include maintenance and accelerator-refresh spending. Model uses upfront capex, level year-end FCF, no residual value and no growth. It is a project sensitivity, not a fair-value or stock-price target.</p></div><div id="valuation-output"></div></div></section><section class="panel panel-pad section-gap"><h3>Why no “market cap per company GW” league table?</h3><p style="font-size:12px">The numerator values every business in the listed company. The denominator would be an incomplete, unevenly observed compute inventory. Mixing those numbers rewards poor disclosure and ignores debt, leases, software, customer economics and other assets. Historical ratios remain in the data room for reproducibility, not as investment conclusions.</p></section>`;}
function updateInvestment(){if(!$('#valuation-output'))return;const market=+$('#v-market').value,g=+$('#v-gw').value,cap=+$('#v-capex').value,fcf=+$('#v-fcf').value,r=+$('#v-rate').value/100,n=+$('#v-years').value;if(![market,g,cap,fcf,r,n].every(Number.isFinite)||market<=0||g<=0||cap<=0||r<=0||n<1){$('#valuation-output').innerHTML='<div class="notice warning">Enter valid positive inputs. Free cash flow may be negative.</div>';return;}let upfront=g*cap,pv=g*fcf*(1-Math.pow(1+r,-n))/r,npv=pv-upfront;$('#valuation-output').innerHTML=`<div class="result-label">PROJECT NPV UNDER THESE ASSUMPTIONS</div><div class="big-number" style="color:${npv<0?'var(--red)':'var(--accent)'}">${npv<0?'−':''}$${fmt(Math.abs(npv),1)}B</div><div class="dashboard-line"><span>Incremental upfront investment</span><strong>${money(upfront,1)}</strong></div><div class="dashboard-line"><span>Upfront investment / assumed equity value</span><strong>${fmt(upfront/market*100,2)}%</strong></div><div class="dashboard-line"><span>Present value of assumed FCF</span><strong>${money(pv,1)}</strong></div><div class="dashboard-line"><span>Project NPV / assumed equity value</span><strong>${fmt(npv/market*100,2)}%</strong></div><div class="equation">NPV = −capex + annual FCF × [1 − (1+r)<sup>−n</sup>] ÷ r</div><p class="footnote">No inference is made that this project, its capacity, pricing or cash flows are actually contracted by the selected company.</p>`;}
function factHTML(f){return `<div class="fact"><div class="label">${esc(f.label)} ${f.date?`· ${esc(f.date)}`:''}</div><div class="value">${esc(f.value)} ${srefs(f.sources)}</div>${f.note?`<p>${esc(f.note)}</p>`:''}</div>`;}
function linkText(t){let out=esc(t);return out.replace(/\[(S\d{2}(?:(?:,|;|\s|-)S?\d{2})*)\]/g,(all)=>{const matched=all.match(/S\d{2}/g)||[];return all+' '+srefs(matched)});}
function reportBlock(b){if(b.type==='paragraph')return `<p>${linkText(b.text).replace(/\n/g,'<br>')}</p>`;if(b.type==='table')return `<div class="table-wrap"><table><tbody>${b.rows.map((row,i)=>`<tr>${row.map(c=>`<${i===0?'th':'td'}>${linkText(c).replace(/\n/g,'<br>')}</${i===0?'th':'td'}>`).join('')}</tr>`).join('')}</tbody></table></div>`;if(b.type==='image')return `<figure style="margin:20px 0"><img src="${b.data}" loading="lazy" alt="${esc(b.caption||'Original report figure — archival')}"/><figcaption class="cell-sub">${esc(b.caption||'Original embedded report figure; original model and dates apply.')}</figcaption></figure>`;return '';}
function reportsView(){const r=A.reports[state.report],sec=r.sections[Math.min(state.section,r.sections.length-1)],matches=r.sections.map((s,i)=>({s,i})).filter(({s})=>!state.reportQ||JSON.stringify(s).toLowerCase().includes(state.reportQ.toLowerCase()));return pagehead('THE COMPLETE REPORT LIBRARY','The detail never disappears.','Every paragraph, table and embedded figure from both attached reports is available here. These are historical originals, retained to expose the evidence and the calculations—not to conceal revisions.',`<button class="btn" data-action="original-file" data-id="${r.filename.replace('.docx','.pdf')}">Original PDF ↓</button>`)+notice(docStatus,true)+`<div class="filterbar"><select id="report-select" aria-label="Select original report"><option value="0" ${state.report===0?'selected':''}>Per-GW-cost revision — original</option><option value="1" ${state.report===1?'selected':''}>Initial report — original</option></select><input id="report-query" type="search" value="${esc(state.reportQ)}" placeholder="Search all sections, tables and text in this report…" aria-label="Search full report"><span class="count">${r.sections.length} sections · ${r.table_count} tables</span></div><div class="report-layout"><aside class="report-toc" aria-label="Report table of contents">${matches.length?matches.map(({s,i})=>`<button data-action="report-section" data-id="${i}" class="${i===state.section?'active':''}"><span class="mono" style="font-size:9px;color:#718b9f">${String(i+1).padStart(2,'0')}</span> &nbsp;${esc(s.title)}</button>`).join(''):'<div class="empty">No matching sections.</div>'}</aside><article class="report-body"><div class="tag-row" style="margin-bottom:22px"><span class="pill archive">Unmodified source text</span><span class="pill">Section ${state.section+1} of ${r.sections.length}</span><button class="text-button" data-action="data-tab" data-id="corrections">See corrections ↗</button></div><h2>${esc(sec.title)}</h2>${sec.blocks.map(reportBlock).join('')}<div class="report-bottom"><button class="btn" data-action="report-prev" ${state.section===0?'disabled':''}>← Previous section</button><button class="btn" data-action="report-next" ${state.section===r.sections.length-1?'disabled':''}>Next section →</button></div><div class="report-preservation">Source: ${esc(r.filename)}. The original PDF, Word document and all embedded chart data are preserved in the data room. Reflowed here for readability; original source files retain the original pagination.</div></article></div>`;}
function dataView(){const tabs=[['sources','Sources'],['corrections','Corrections'],['workbooks','Excel audit viewer'],['models','All model records'],['files','Original attachments']];return pagehead('THE DATA ROOM','Nothing important is hidden behind a chart.','Inspect references, source vintages, corrections, every workbook cell and formula, both original models, and the exact original attachments.',`<button class="btn primary" data-action="export-all">Export atlas data ↓</button>`)+`<div class="tabs">${tabs.map(([v,l])=>`<button data-action="data-tab" data-id="${v}" class="${state.dataTab===v?'active':''}">${l}</button>`).join('')}</div>`+({sources:sourcesView,corrections:correctionsView,workbooks:workbooksView,models:modelsView,files:filesView}[state.dataTab])();}
function sourcesView(){const ss=D.sources.filter(s=>!state.dataQ||JSON.stringify(s).toLowerCase().includes(state.dataQ.toLowerCase()));return `<div class="disclosure-grid"><section class="panel"><div class="small-title">Original + enriched references</div><strong>${D.sources.length}</strong><p>49 original references and 15 enrichment records. Source dates and review status remain attached.</p></section><section class="panel"><div class="small-title">A complete source extraction</div><strong>${A.workbooks.reduce((n,w)=>n+w.sheets.reduce((n,s)=>n+s.cells.length,0),0).toLocaleString()}</strong><p>Nonempty and formula cells across both workbooks. Cached values are displayed, not recalculated.</p></section><section class="panel"><div class="small-title">A source is not a certainty score</div><strong>A / B / C</strong><p>Issuer disclosure, independent model and imported estimate are different evidence types—not additive capacity tiers.</p></section></div><div class="filterbar section-gap"><input type="search" id="data-query" value="${esc(state.dataQ)}" placeholder="Search source ID, issuer, title or use…" aria-label="Search source register"><span class="count">${ss.length} references</span></div><div class="table-wrap"><table><thead><tr><th>ID / evidence type</th><th>Publisher / exact source</th><th>Date in register</th><th>Claim coverage</th></tr></thead><tbody>${ss.map(s=>`<tr class="clickable" data-action="source" data-id="${s.id}" tabindex="0"><td><span class="source-chip">${s.id}</span><br><span class="cell-sub">${esc(s.category)}</span></td><td><span class="cell-title">${esc(s.issuer)}</span><span class="cell-sub">${esc(s.title)}</span></td><td>${esc(s.date)}<br><span class="cell-sub">${s.id.startsWith('N')?'Build enrichment':'Imported reference'}</span></td><td>${esc(s.use)} ↗</td></tr>`).join('')}</tbody></table></div><p class="footnote">Source IDs are links into evidence cards. External source pages require a connection; the app, data, report text, original attachments and cartography are embedded and operate offline. “Current” in an original reference has not been converted into a fresh verification date.</p>`;}
function correctionsView(){return notice('Corrections are applied to the app’s interpretive views. The source workbooks and PDFs remain byte-for-byte originals for reproducibility; no claim is made that these embedded archival files have been rewritten.')+D.corrections.map(c=>`<article class="correction-card"><div class="flex"><span class="pill archive">${c.id} · ${c.impact} materiality</span>${srefs(c.sources)}</div><h3>${esc(c.title)}</h3><div class="before-after"><div><span>EARLIER TREATMENT</span>${esc(c.before)}</div><div><span>APP TREATMENT</span>${esc(c.after)}</div></div><p>${esc(c.why)}</p></article>`).join('');}
function colName(n){let s='';while(n){n--;s=String.fromCharCode(65+n%26)+s;n=Math.floor(n/26)}return s;}
function workbooksView(){const b=A.workbooks[state.book],sh=b.sheets[Math.min(state.sheet,b.sheets.length-1)],map=new Map(sh.cells.map(c=>[c.address,c]));return notice('This is a read-only audit extraction of the original Excel files. Formula expressions and cached cell values are preserved. They are not recalculated or validated as current business facts.',true)+`<div class="filterbar"><select id="book-select" aria-label="Select workbook">${A.workbooks.map((b,i)=>`<option value="${i}" ${state.book===i?'selected':''}>${i===0?'Per-GW revision':'Initial workbook'}</option>`).join('')}</select><select id="sheet-select" aria-label="Select worksheet">${b.sheets.map((s,i)=>`<option value="${i}" ${state.sheet===i?'selected':''}>${esc(s.name)}</option>`).join('')}</select><button class="btn small" data-action="export-sheet">Export sheet CSV ↓</button><button class="btn small" data-action="original-file" data-id="${b.filename}">Original XLSX ↓</button><span class="count">${sh.cells.length} populated / formula cells · click any cell</span></div><div class="sheet-grid"><table aria-label="${esc(sh.name)} original worksheet"><thead><tr><th></th>${Array.from({length:sh.max_col},(_,i)=>`<th>${colName(i+1)}</th>`).join('')}</tr></thead><tbody>${Array.from({length:sh.max_row},(_,ri)=>`<tr><td class="row-number">${ri+1}</td>${Array.from({length:sh.max_col},(_,ci)=>{const addr=colName(ci+1)+(ri+1),c=map.get(addr);return `<td class="${c?.formula?'formula':''}" data-action="cell" data-id="${addr}" tabindex="0" aria-label="Cell ${addr}${c?.formula?', formula':''}">${c?esc(c.value??(c.formula?'[No cached value]':'')):''}</td>`}).join('')}</tr>`).join('')}</tbody></table></div><p class="footnote">Blue-tinted values identify formula cells. Click to inspect the exact formula, stored result and original address. Headings and cell content are preserved; the app does not reproduce Excel formatting or recalculate formulas.</p>`;}
function modelsView(){const m=A.legacy[state.book]||A.legacy[0];return `<div class="filterbar"><select id="model-select" aria-label="Select original data model"><option value="0" ${state.book===0?'selected':''}>Per-GW model — archival original</option><option value="1" ${state.book===1?'selected':''}>Initial model — archival original</option></select><button class="btn" data-action="export-legacy">Export entire original JSON ↓</button><button class="btn" data-action="export-all">Export enriched app JSON ↓</button></div>${notice('Every original field is retained, including the invalid “reconciled current fleet” rule and superseded stock-per-GW ratios. Their presence in this audit viewer is not an endorsement.',true)}${Object.entries(m).map(([k,v])=>`<details class="raw-details"><summary>${esc(k)} <span class="muted">· ${Array.isArray(v)?v.length+' records':typeof v==='object'?Object.keys(v).length+' fields':'metadata'}</span> <button class="text-button" style="float:right" data-action="export-model-key" data-id="${esc(k)}">JSON ↓</button></summary>${Array.isArray(v)?v.map((r,i)=>`<details class="raw-details" style="margin:8px 12px"><summary>${String(i+1).padStart(2,'0')} · ${esc(r.company||r.site||r.benchmark||r.platform||r.vendor||r.title||r.owner||'Record')}</summary><pre>${esc(JSON.stringify(r,null,2))}</pre></details>`).join(''):`<pre>${esc(JSON.stringify(v,null,2))}</pre>`}</details>`).join('')}`;}
function filesView(){return `<div class="panel panel-pad"><div class="panel-head"><h2>Exact originals, with a checksum trail</h2><span class="pill archive">Archival source files</span></div><p style="font-size:12px">These eight files are the actual attachments available to this build, not the absent later audited app mentioned in an earlier conversation. Each is embedded in this app for offline retrieval, and also included in the source package.</p>${D.manifest.map(f=>`<div class="file-row"><span class="file-icon">${f.filename.split('.').pop().toUpperCase()}</span><div style="flex:1;min-width:0"><div class="file-name">${esc(f.filename)}</div><div class="file-meta">${fmt(f.bytes/1048576,2)} MB · SHA256 ${f.sha256}</div></div><button class="btn small" data-action="original-file" data-id="${f.filename}">Retrieve original ↓</button></div>`).join('')}</div><div class="grid-two section-gap"><section class="panel panel-pad"><h3>Preservation coverage</h3>${A.reports.map(r=>`<div class="fact"><div class="label">${esc(r.filename)}</div><div class="value">${r.sections.length} sections · ${r.table_count} tables</div><p>Every extracted block is available in the full report library.</p></div>`).join('')}${A.workbooks.map(b=>`<div class="fact"><div class="label">${esc(b.filename)}</div><div class="value">${b.sheets.length} sheets · ${fmt(b.sheets.reduce((n,s)=>n+s.cells.length,0))} cells</div></div>`).join('')}</section><section class="panel panel-pad"><h3>Attribution and limitations</h3><p style="font-size:12px">The independent site estimates and original cost model cite Epoch AI. World outlines use Natural Earth public-domain cartography. Map anchors are approximations assigned from site names or regional descriptions; geopolitical boundaries are displayed for orientation, not as a political statement.</p><p style="font-size:12px">The app has no live market feed, satellite feed, background updating service or guarantee of completeness. Source links leave the offline app and require internet access. Browser-saved notes remain local unless exported.</p><button class="btn" data-action="method">Read the evidence guide ↗</button></section></div>`;}
const STOPS=[
{title:'The headline versus the IT load',sub:'01 / NEW CARLISLE',site:()=>D.sites.find(s=>s.name==='New Carlisle'),text:'Separate an approximately 2.3 GW gross facility envelope from the dated 1,925 MW IT projection. A power boundary can change an entire cost comparison.',sources:['N01']},
{title:'One campus, different balance sheets',sub:'02 / HELIOS',site:()=>D.sites.find(s=>s.name==='Helios'),text:'Follow Galaxy’s facility, CoreWeave’s compute service and their power definitions. A gross envelope, contracted critical load and active estimate are different quantities.',sources:['N04','S42']},
{title:'Chip count is not equivalent output',sub:'03 / ZHANGBEI',site:()=>D.sites.find(s=>s.name==='Zhangbei'),text:'The H20-based site model makes the distinction visible: physical accelerators, IT power and theoretical H100-equivalents measure different things.',sources:['N05']},
{title:'A domestic accelerator ecosystem',sub:'04 / HORINGER',site:()=>D.sites.find(s=>s.name==='Horinger'),text:'Ascend hardware belongs in the landscape. A modeled site estimate remains a modeled site estimate—not Huawei’s entire fleet or a measured workload benchmark.',sources:['N06']},
{title:'Utilization turns capacity into economics',sub:'05 / THE COST LAB',view:'costs',text:'Change equipment life and productive utilization. Watch the unit economics move while installed GW stays unchanged. Then inspect the assumptions behind the result.',sources:['S03']}
];
function storiesView(){return pagehead('GUIDED EXPLORATIONS','Find a thread. Follow it all the way down.','A catalog-style route through the evidence: start with a question, visit the objects, then inspect the underlying record. The globe and source library stay linked throughout.',`<button class="btn primary" data-action="tour-start">Start the complete tour →</button>`)+`<div class="story-list">${STOPS.map((s,i)=>`<button class="story-card" style="min-height:220px" data-action="tour-at" data-id="${i}"><span class="number">${s.sub}</span><span class="arrow">↗</span><h3 style="font-size:29px">${s.title}</h3><p style="font-size:12px">${s.text}</p></button>`).join('')}<section class="panel panel-pad"><h3>Explore without the tour</h3><p style="font-size:12px">Use the global search to jump directly to a campus, chip, source ID or phrase in the report. Save dossiers to your research shelf and export your notes.</p><div class="link-list"><button data-action="search"><span>Search everything</span><kbd>/</kbd></button><button data-action="nav" data-id="watchlist"><span>Open your research shelf</span><span>☆</span></button><button data-action="data-tab" data-id="corrections"><span>Read the correction trail</span><span>↗</span></button></div></section></div>`;}
function watchlistView(){const ss=saved.favorites.map(site).filter(Boolean);return pagehead('YOUR RESEARCH SHELF','Keep the sites that matter to you.',storageOK?'Stars and notes are saved locally in this browser. Export a research session to move them elsewhere; nothing is uploaded.':'Persistent browser storage is unavailable. Stars and notes remain in this open session; export a research session before closing. Nothing is uploaded.',`<button class="btn" data-action="import-session">Import session ↑</button><button class="btn primary" data-action="export-session">Export session ↓</button>`)+(ss.length?siteCards(ss):`<div class="empty"><h3>Your shelf is ready.</h3><p>Star a facility in the directory or inside a dossier. Add a diligence note; it will stay attached to that record.</p><button class="btn" data-action="nav" data-id="facilities">Explore facilities →</button></div>`)+`<section class="panel panel-pad section-gap"><h3>Saved notes</h3>${Object.entries(saved.notes).filter(([k,v])=>v.trim()).map(([id,text])=>`<div class="fact"><button class="text-button" data-action="site" data-id="${esc(id)}">${esc(site(id)?.name||id)} ↗</button><p>${esc(text)}</p></div>`).join('')||'<p style="font-size:12px">Open a facility dossier to add your first note.</p>'}</section>`;}
function openDrawer(kind,id,opts={}){if(!opts.back&&state.drawer)state.drawerHistory.push(state.drawer);if(!state.drawer){lastFocused=document.activeElement;state.drawerHistory=[];}state.drawer={kind,id};if(['site','company','source'].includes(kind))history.replaceState(null,'','#'+kind+'/'+encodeURIComponent(id));$('#drawer-scrim').hidden=false;$('#drawer').hidden=false;document.body.style.overflow='hidden';$('#drawer-back').style.visibility=state.drawerHistory.length?'visible':'hidden';$('#drawer-type').textContent=({site:'FACILITY DOSSIER',company:'COMPANY DOSSIER',source:'SOURCE & PROVENANCE',cost:'COST BENCHMARK',contract:'CONTRACT / PROGRAM',method:'EVIDENCE GUIDE',cell:'ORIGINAL EXCEL CELL',footnote:'FOOTNOTE OBLIGATIONS',hardware:'HARDWARE NORMALIZATION',help:'EXPLORER CONTROLS',cluster:'NEARBY SITE RECORDS',record:'SOURCE RECORD'})[kind]||'RESEARCH DOSSIER';let html='';if(kind==='site')html=siteDossier(site(id));else if(kind==='company')html=companyDossier(company(id));else if(kind==='source')html=sourceDossier(source(id));else if(kind==='cost')html=costDossier(D.costs.find(x=>x.id===id));else if(kind==='contract')html=contractDossier(D.contracts.find(x=>x.id===id));else if(kind==='method')html=methodDossier();else if(kind==='help')html=helpDossier();else if(kind==='cluster'){const ss=id.split('|').map(site).filter(Boolean);html=`<div class="eyebrow">GEOGRAPHIC NEIGHBORS</div><h1>${ss.length} nearby records</h1><p>Markers are clustered visually, not merged financially. City-level anchors can place different facilities at the same point.</p><div class="panel">${siteItems(ss)}</div><p class="footnote">Zoom further or select a record. Co-location does not establish a common campus, ownership or power denominator.</p>`;}else if(kind==='hardware'){const n=D.normalization[+id];html=`<h1>${esc(n.platform)}</h1><div class="dossier-hero"><div class="small-title">ORIGINAL COMPARISON MODEL</div><p>${esc(n.notes)}</p></div>${kv({'Platform power':n.system_kw+' kW','Accelerators per platform':n.physical_gpu,'External IT overhead':fmt(n.overhead_pct*100)+'%','H100e / accelerator':fmt(n.h100e_per_gpu,5),'IT kW / accelerator':fmt(n.kw_per_gpu_it,5),'Physical accelerators / IT GW':fmt(n.physical_per_it_gw),'H100e / IT GW':fmt(n.h100e_per_it_gw),'PUE':n.pue})}<div class="equation">${n.system_kw} ÷ ${n.physical_gpu} × (1 + ${n.overhead_pct}) = ${fmt(n.kw_per_gpu_it,5)} IT kW per accelerator</div>${srefs(n.sources)}${raw(n)}`;}else if(kind==='footnote'){const c=company(id);html=`<h1>${esc(c.name)}</h1><div class="eyebrow">ORIGINAL FINANCIAL FOOTNOTE MODEL</div>${notice('Financial records are imported from the earlier report. Source dates, scopes and overlaps must be verified before investment reliance.',true)}${c.commitment?kv(c.commitment):'<p>No populated financial record.</p>'}${srefs(c.commitment?.sources)}${raw(c.commitment)}<h2>Associated contracts</h2>${D.contracts.filter(x=>x.company_ids.includes(id)).map(x=>`<div class="fact"><button class="text-button" data-action="contract" data-id="${x.id}">${esc(x.vendor)} / ${esc(x.counterparty)} →</button></div>`).join('')}`;}else if(kind==='cell'){const b=A.workbooks[state.book],sh=b.sheets[state.sheet],c=sh.cells.find(x=>x.address===id);html=`<div class="eyebrow">READ-ONLY ORIGINAL WORKBOOK</div><h1>${esc(sh.name)}!${esc(id)}</h1><p>${esc(b.filename)}</p>${kv({'Address':id,'Cached value':c?.value??'(empty)','Formula':c?.formula??'(no formula)','Row':c?.row,'Column':c?.col})}${notice('Cached values are the stored results from the source XLSX, not freshly calculated results. A valid stored formula is not evidence that its business assumptions are valid.',true)}${raw(c||{address:id,value:null,formula:null})}`;}else if(kind==='record'){html=`<h1>Original data record</h1>${raw(JSON.parse(id),'Full record')}`;}$('#drawer-content').innerHTML=html;$('#drawer').scrollTop=0;if(opts.focus!==false)setTimeout(()=>$('#drawer .drawer-head .icon-button').focus({preventScroll:true}),20);if(kind==='site'&&globe&&site(id)?.lat!=null)globe.flyTo(site(id).lat,site(id).lon,globe.zoom<1.6?1.6:globe.zoom);}
function closeDrawer(){if($('#drawer').hidden)return;state.drawer=null;state.drawerHistory=[];history.replaceState(null,'','#'+state.view);$('#drawer').hidden=true;$('#drawer-scrim').hidden=true;document.body.style.overflow='';if(lastFocused?.isConnected)lastFocused.focus({preventScroll:true});}
function siteDossier(s){if(!s)return '<div class="empty">Record not found.</div>';const ss=s.snapshot,t=s.target,c=company(s.primary_company),contracts=D.contracts.filter(x=>x.company_ids.some(id=>s.company_ids.includes(id))),nrows=s.raw.length;const similar=D.sites.filter(x=>x.id!==s.id&&x.primary_company===s.primary_company).slice(0,7);return `<div class="flex" style="justify-content:space-between;margin-bottom:19px"><div class="tag-row">${rolePill(s)}${phasePill(s)}</div>${star(s.id)}</div><h1>${esc(s.name)}</h1><div class="drawer-meta">${esc(s.location)}<br>${esc(s.owner_label)} · ${esc(s.country)}</div><div class="drawer-actions"><button class="btn primary" data-action="locate" data-id="${s.id}" ${s.lat==null?'disabled':''}>Locate on globe ↗</button><button class="btn" data-action="site-export" data-id="${s.id}">Dossier JSON ↓</button><button class="btn" data-action="print">Print dossier</button></div><div class="metric-grid">${metric(ss?fmt(ss.it_mw):'—','Snapshot IT MW',ss?esc(ss.date)+' · '+(s.review==='archive'?'imported estimate':'modeled estimate'):'No comparable operating IT measure')}${metric(ss?fmt(ss.h100e_k,1)+'k':'—','Snapshot H100e','Theoretical compute model; not workload parity')}${metric(t?fmt(t.it_mw):'—','Projected IT MW',t?esc(t.date||'Date not supplied')+' · not a signed supply claim':'No matched target phase')}</div>${ss?`<p class="footnote">Snapshot source ${srefs(ss.sources)} ${t?` · Target source ${srefs(t.sources)}`:''}. Source dates are not live operational telemetry.</p>`:''}<h2>The facility evidence</h2>${(s.facts||[]).map(factHTML).join('')}<div class="grid-two"><section class="panel panel-pad"><h3>Modeled replacement cost</h3><div style="font:28px Georgia,serif;color:#d9ece5;margin-bottom:9px">${ss?.cost_b!=null?money(ss.cost_b,1):'Not established'}</div><p style="font-size:10px;margin-bottom:0">${ss?.cost_b!=null?'Engineering-model full-stack replacement convention. Not actual reported project capex.':'No matched full-stack project cost disclosure in this record.'}</p>${srefs(ss?.sources||s.sources)}</section><section class="panel panel-pad"><h3>Implied model cost per IT GW</h3><div style="font:28px Georgia,serif;color:#d9ece5;margin-bottom:9px">${ss?.it_mw>0&&ss.cost_b!=null?money(ss.cost_b/(ss.it_mw/1000),2):'Not established'}</div><p style="font-size:10px;margin-bottom:0">${ss?.it_mw>0&&ss.cost_b!=null?`${money(ss.cost_b,1)} ÷ ${gw(ss.it_mw)} IT GW. Shared model convention, not vendor price discovery.`:'No denominator is inferred from cabinet counts, floor area or unspecified computing units.'}</p></section></div>${t?`<div class="fact"><div class="label">Projected phase record ${srefs(t.sources)}</div><div class="value">${fmt(t.it_mw)} MW IT · ${fmt(t.h100e_k,1)}k H100e · ${money(t.cost_b,1)}</div><p>${esc(t.date||'Date not specified')} · projected end-state. Do not add to the current phase as wholly incremental.</p></div>`:''}<h2>Ownership and economic roles</h2><div class="table-wrap"><table><thead><tr><th>Role</th><th>Entity</th><th>Attribution / boundary</th></tr></thead><tbody>${s.roles.map(r=>`<tr><td>${esc(r.role)}</td><td>${esc(r.entity)}</td><td>${esc(r.basis)}</td></tr>`).join('')}</tbody></table></div><h2>Silicon and useful compute</h2>${s.hardware.length?`<div class="table-wrap"><table><thead><tr><th>Accelerator</th><th class="number">Modeled count</th><th>Basis</th></tr></thead><tbody>${s.hardware.map(h=>`<tr><td>${esc(h.model)}</td><td class="number">${fmt(h.count)}</td><td>${esc(h.basis)} ${srefs(h.sources)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="notice compact">The source record does not provide a verified chip-by-chip inventory. The app does not reverse-engineer one from the H100e figure.</div>'}<p class="footnote">H100e normalizes theoretical eight-bit arithmetic. It does not normalize memory bandwidth, interconnect, software, training efficiency, inference latency or commercial availability.</p><h2>Buildout and phase evidence</h2>${s.timeline.length?`<div class="timeline">${s.timeline.map(t=>`<div class="timeline-item ${t.kind}"><div class="date">${esc(t.date)} · ${esc(t.kind.toUpperCase())}</div><strong>${esc(t.label)}</strong>${t.mw!=null?`<p>${fmt(t.mw)} MW IT ${srefs(t.sources)}</p>`:srefs(t.sources)}</div>`).join('')}</div>`:`<div class="notice compact">No complete historical commissioning series is supplied for this campus. ${ss?'Only the dated snapshot':'The project record'}${t?' and a target phase are':' is'} available. Intermediate milestones are not invented.</div>`}<h2>What not to infer</h2>${s.caveats.map(x=>`<div class="notice compact warning">${esc(x)}</div>`).join('')}<h2>Related company-level programs</h2><p class="footnote" style="margin-top:0">These records share a company association; they are not automatically allocated to this specific facility.</p>${contracts.length?`<div class="link-list">${contracts.map(x=>`<button data-action="contract" data-id="${x.id}"><span>${esc(x.vendor)} → ${esc(x.counterparty)}</span><span>↗</span></button>`).join('')}</div>`:'<p>No mapped company-level contract record in this collection.</p>'}<h2>Follow the company</h2><div class="tag-row">${s.company_ids.map(id=>company(id)?`<button class="btn small" data-action="company" data-id="${id}">${esc(company(id).name)} ↗</button>`:'').join('')}</div><h2>Map precision</h2>${kv({'Cartographic anchor':s.lat==null?'Not mapped':`${s.lat.toFixed(2)}°, ${s.lon.toFixed(2)}°`,'Accuracy':s.coordinate_precision,'Source of anchor':'Manually assigned from a named city, county, district or region. Not a source-surveyed facility centroid.'})}<h2>Source trail</h2>${s.sources.map(source).filter(Boolean).map(sourceCard).join('')}<h2>Original rows and structured dossier</h2><p class="footnote">${nrows} original report row${nrows===1?'':'s'} attached. The revised phase display never overwrites these source records.</p>${s.raw.map(r=>raw(r,`${r.table} · original row ${r.row}`)).join('')}${raw(s,'Complete enriched dossier JSON')}<h2>Your diligence note</h2><textarea id="facility-note" data-note="${s.id}" placeholder="Questions, risks, commissioning checks…" aria-label="Private local note for ${esc(s.name)}">${esc(saved.notes[s.id]||'')}</textarea><p class="footnote">${storageOK?"Saved in this browser only.":"Persistent browser storage is unavailable. Notes remain in this open session only."} Export your session from the research shelf for a portable backup.</p>${similar.length?`<h2>More in this operator’s footprint</h2><div class="link-list">${similar.map(x=>`<button data-action="site" data-id="${x.id}"><span>${esc(x.name)}</span><span>↗</span></button>`).join('')}</div>`:''}`;}
function companyDossier(c){if(!c)return '<p>Company not found.</p>';const ss=D.sites.filter(s=>s.company_ids.includes(c.id)),f=companyFootprint(c),contracts=D.contracts.filter(x=>x.company_ids.includes(c.id));return `<div class="tag-row" style="margin-bottom:20px"><span class="pill">${esc(c.region)}</span><span class="pill">${esc(c.role)}</span></div><h1>${esc(c.name)}</h1><div class="drawer-meta">${esc(c.ticker)} · identifier only, not a live quote</div><div class="drawer-actions"><button class="btn primary" data-action="filter-company" data-id="${c.id}">Explore linked facilities ↗</button><button class="btn" data-action="invest-company" data-id="${c.id}">Investment lens ↗</button><button class="btn" data-action="toggle-compare" data-id="${c.id}">${state.compare.includes(c.id)?'Remove comparison':'Add to comparison'}</button></div><div class="dossier-hero"><div class="small-title">${esc(c.headline)}</div><p>${esc(c.thesis)}</p></div><div class="metric-grid">${metric(ss.length,'Linked site / project dossiers','Includes customer, owner and supply relationships')}${metric(f.count?gw(f.mw):'—','Primary-owner snapshot GW',`${f.count} named sites · not a fleet total`)}${metric('Unknown','Complete operating fleet','This source collection does not establish a census')}</div><h2>Investment interpretation</h2><div class="notice warning">${esc(c.risk)}</div><h3>Monitor</h3><p>${esc(c.watch)}</p><p class="footnote">Analyst synthesis, not a price target. ${srefs(c.sources)}</p>${c.facts.length?'<h2>Additional company disclosures</h2>'+c.facts.map(factHTML).join(''):''}<h2>Named facilities and projects</h2>${ss.length?`<div class="panel">${siteItems(ss)}</div>`:'<div class="notice">No sufficiently identified site record is populated for this company in this source set. That is not a statement that it lacks compute.</div>'}<h2>Programs and counterparties</h2>${contracts.length?`<div class="link-list">${contracts.map(x=>`<button data-action="contract" data-id="${x.id}"><span>${esc(x.vendor)} / ${esc(x.counterparty)}</span><span>↗</span></button>`).join('')}</div>`:'<p>No comparable capacity program is populated here.</p>'}<h2>Financial footnote trail</h2>${c.commitment?`<div class="notice compact warning">${esc(c.commitment.period)} — imported original financial disclosure; not newly re-underwritten.</div>${kv({'Cash capex ($B)':c.commitment.capex_b,'Operating cash flow ($B)':c.commitment.ocf_b,'Uncommenced leases ($B)':c.commitment.uncommenced_leases_b,'Purchase / contractual commitments ($B)':c.commitment.purchase_or_contract_b,'Debt ($B)':c.commitment.debt_b,'RPO / backlog ($B)':c.commitment.rpo_b,'Interpretation':c.commitment.notes})}${srefs(c.commitment.sources)}<button class="text-button" style="display:block;margin-top:14px" data-action="footnote" data-id="${c.id}">Inspect original footnote fields →</button>`:'<p>No full financial footnote extraction is available for this company in the attached files. Do not substitute a made-up cost per GW.</p>'}<h2>Sources</h2>${c.sources.map(source).filter(Boolean).map(sourceCard).join('')||'<p>No claim-level source populated. Company card is a research coverage placeholder, not a quantitative conclusion.</p>'}<h2>Historical model preservation</h2>${c.legacy_summary?raw(c.legacy_summary,'Original company summary — superseded operating-fleet arithmetic'):''}${c.stock?raw(c.stock,'Original market snapshot and ratios — unverified 2026-08-31 archive'):''}${raw(c,'Complete company research record')}`;}
function sourceCard(s){return `<div class="source-card"><div class="flex"><button class="source-chip" data-action="source" data-id="${s.id}">${s.id}</button><span class="cell-sub">${esc(s.issuer)} · ${esc(s.date)}</span></div><div class="source-title">${esc(s.title)}</div><p>${esc(s.use)}</p>${/^https?:\/\//.test(s.url)?`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">Open original source ↗</a>`:'<p>No conventional source URL available in the original ledger.</p>'}</div>`;}
function sourceDossier(s){if(!s)return '<p>Source not found.</p>';const ss=D.sites.filter(x=>x.sources.includes(s.id)),cs=D.companies.filter(c=>c.sources.includes(s.id)),deals=D.contracts.filter(c=>ids(c.sources).includes(s.id)),ben=D.costs.filter(c=>ids(c.sources).includes(s.id));return `<div class="eyebrow">${s.id} / ${esc(s.category)}</div><h1>${esc(s.title)}</h1><div class="drawer-meta">${esc(s.issuer)} · ${esc(s.date)}</div>${notice(esc(s.review||'Imported source; not re-verified'),!s.id.startsWith('N'))}<h2>Claims this source supports</h2><p>${esc(s.use)}</p>${s.date_note?`<p class="footnote">${esc(s.date_note)}</p>`:''}${s.access_note?`<p class="notice warning">${esc(s.access_note)}</p>`:''}${/^https?:\/\//.test(s.url)?`<a class="btn primary" href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">Open the original source ↗</a><p class="footnote" style="overflow-wrap:anywhere">${esc(s.url)}</p>`:notice('The original ledger uses a finance:// reference that cannot be opened as a conventional web citation. Do not treat the old market snapshot as a verified live quote.',true)}<h2>Referenced facilities</h2>${ss.length?`<div class="panel">${siteItems(ss)}</div>`:'<p>No specific facility linkage recorded; this may be a company or methodological source.</p>'}<h2>Company connections</h2><div class="tag-row">${cs.map(c=>`<button class="btn small" data-action="company" data-id="${c.id}">${esc(c.name)} ↗</button>`).join('')||'<span class="muted">No direct company mapping.</span>'}</div>${deals.length?`<h2>Capacity programs</h2><div class="link-list">${deals.map(c=>`<button data-action="contract" data-id="${c.id}"><span>${esc(c.vendor)} / ${esc(c.counterparty)}</span><span>↗</span></button>`).join('')}</div>`:''}${ben.length?`<h2>Cost benchmarks</h2><div class="link-list">${ben.map(c=>`<button data-action="cost" data-id="${c.id}"><span>${esc(c.benchmark)}</span><span>↗</span></button>`).join('')}</div>`:''}<h2>Exact ledger entry</h2>${raw(s)}<p class="footnote">A linked source can be a modeled estimate or an announcement rather than a filing. Numerical scope, source vintage and uncertainty take precedence over the visual prominence of a chart.</p>`;}
function costDossier(c){return `<div class="eyebrow">${esc(c.layer)}</div><h1>${esc(c.benchmark)}</h1>${notice(esc(c.caveat),true)}<div class="metric-grid">${metric(c.capacity_mw==null?'—':fmt(c.capacity_mw),'Referenced capacity MW','Power boundary in the source controls')}${metric(c.nominal_b_per_gw==null?'—':'$'+fmt(c.nominal_b_per_gw,2),'Original nominal $B/GW','May be lifetime lease or capex, not the same cost layer')}${metric(c.annual_b_per_gw==null?'—':'$'+fmt(c.annual_b_per_gw,2),'Original $B/GW-year','Nominal annualization; not discounted TCO')}</div>${kv({'Cost layer':c.layer,'Contract face value ($B)':c.contract_value_b,'Capex ($B)':c.capex_b,'Contract term (years)':c.term_years,'Electricity included':c.power_included,'Hardware included':c.hardware_included,'Original $/kW-month':c.usd_per_kw_month,'Review status':c.review})}<h2>Arithmetic and interpretation</h2><div class="equation">Nominal $B/GW = nominal contract value or capex ($B) ÷ disclosed GW<br>Nominal $B/GW-year = contract value ($B) ÷ GW ÷ contractual years</div><p>The numerators are not interchangeable. Construction costs, long-term facility rents, equipment bills and managed compute fees cover different layers. Retain the disclosed term, power and hardware inclusion.</p><h2>Source trail</h2>${ids(c.sources).map(source).filter(Boolean).map(sourceCard).join('')}<h2>Unmodified model fields</h2>${raw(c)}`;}
function contractDossier(c){return `<div class="eyebrow">${esc(c.status)}</div><h1>${esc(c.vendor)}<br><span style="color:#94b2bd">${esc(c.counterparty)}</span></h1>${notice(esc(c.overlap_note),true)}<div class="metric-grid">${metric(c.capacity_gw==null?'—':fmt(c.capacity_gw,3),'Referenced GW',esc(c.capacity_type))}${metric(c.contract_value_b==null?'—':money(c.contract_value_b,1),'Reference face value',esc(c.price_basis))}${metric(c.term_years==null?'—':fmt(c.term_years),'Term in years','Not a commissioned-life or hardware-life estimate')}</div>${kv({'Capacity qualifier':c.capacity_type,'Status':c.status,'Near-term milestone':c.near_term,'Value scope':c.price_basis,'Overlap / exclusions':c.overlap_note,'Evidence handling':c.review})}<h2>Linked companies</h2><div class="tag-row">${c.company_ids.map(company).filter(Boolean).map(x=>`<button class="btn small" data-action="company" data-id="${x.id}">${esc(x.name)} ↗</button>`).join('')}</div><h2>What this does not establish</h2><p>This record does not on its own demonstrate current accelerator availability, utilization, a matched facility-level delivery schedule, a net-new quantity outside other programs, or a standardized all-in compute price.</p><h2>Original announcement / filing trail</h2>${ids(c.sources).map(source).filter(Boolean).map(sourceCard).join('')}<h2>Every source-model field</h2>${raw(c.raw,'Unmodified original program record')}`;}
function methodDossier(){return `<div class="eyebrow">READING THE LANDSCAPE</div><h1>Evidence before aggregation.</h1><p>This atlas is an explorable research collection. It is not a census of global compute, an availability API or a live valuation terminal.</p><h2>Three power boundaries</h2>${kv({'Accelerator TDP':'Chip thermal design power. It excludes host CPUs, network, storage and other IT overhead.','IT power':'Power for the equipment inside the IT boundary. Site estimates need not isolate accelerators from every other load.','Facility / gross power':'Includes cooling and power overhead. Facility power ÷ PUE can estimate IT load only when PUE and the denominator scope are appropriate.'})}<h2>Four evidence states</h2><div class="fact">${rolePill({review:'reviewed-model'})}<p>An independent site model whose source page or extract was reviewed in this build. Still not a measured operating disclosure.</p></div><div class="fact">${rolePill({review:'archive'})}<p>Original site estimate retained from the attached model. It is not re-verified as current.</p></div><div class="fact">${rolePill({review:'primary-noncomparable'})}<p>A primary or government disclosure identifies the project, but its unit does not establish comparable AI IT MW.</p></div><div class="fact">${rolePill({review:'contract-record'})}<p>Capacity is associated with a disclosed contract. That does not establish active or utilized compute.</p></div><h2>Targets are not additions</h2><p>Target figures generally describe end-states. Do not add a target to its current phase or aggregate overlapping landlord, cloud and model-customer records. “Up to,” an option, an internal roadmap and a firm supply contract carry different obligations.</p><h2>Comparable hardware is a model</h2><p>H100e follows theoretical dense-equivalent eight-bit throughput in the underlying methodology. It is not equal training time, inference speed or rented cloud-instance performance. B100 power is an explicit approximation in the supplied normalization model.</p>${srefs(['S02','S05','S06','S07'])}<h2>Costs: do not mix the layers</h2><p>Facility capex, GPU equipment, lease face values and managed-service purchase commitments are shown separately. Common replacement cost is a scenario convention, not proof of actual company expenditure or equity value.</p><h2>Geography and completeness</h2><p>Coordinates are city, county, district or state anchors assigned from names, not surveyed facility locations. Unresolved places remain searchable and unmapped. Nearby markers cluster only visually. Named-site sums are incomplete and cannot rank entire corporate fleets reliably.</p><h2>Historical originals are preserved</h2><p>Both PDF and Word versions, both Excel workbooks and both JSON models are embedded exactly. The app exposes revised interpretations but does not silently alter the archival files or claim they are freshly audited.</p><h2>Investment discipline</h2><p>The original 31 August 2026 market snapshot is not independently verified or live. Compare funding needs, margin, utilization and obligations—not market cap divided by a selectively observed fleet. The valuation lab uses explicit user assumptions, not analyst price targets.</p><h2>Coverage that remains unknown</h2><p>Complete fleets, precise coordinates, actual project procurement bills, current chip inventories and signed site delivery calendars are not publicly established for every record. The app leaves those fields unknown rather than fabricating precision.</p><button class="btn primary" data-action="data-tab" data-id="corrections">Open the correction register →</button>`;}
function helpDossier(){return `<h1>Explore your way.</h1><p>The globe, companies, facilities, costs, contracts and reports are connected. Clicking a source badge opens the evidence trail.</p><div class="help-grid"><kbd>/</kbd><span>Search everything</span><kbd>⌘ / Ctrl K</kbd><span>Open search</span><kbd>Escape</kbd><span>Close search or a dossier</span><kbd>← ↑ → ↓</kbd><span>Rotate the focused globe</span><kbd>+ / −</kbd><span>Zoom the focused globe</span><kbd>Drag</kbd><span>Rotate the globe with mouse or touch</span><kbd>Scroll</kbd><span>Zoom over the globe</span><kbd>☆</kbd><span>Save a facility to your local research shelf</span></div><h2>Every record has a way in</h2><p>Use the keyboard-accessible facility list as an alternative to selecting map markers. Click a company to see its associated sites and obligations. Select up to four companies for a side-by-side comparison.</p><h2>Reading original calculations</h2><p>The Excel audit viewer retains every populated cell and original formula. The report library preserves all extracted paragraphs, tables and figures. The data room includes exact original downloads and file hashes.</p><h2>Offline and private</h2><p>All application logic, datasets, original attachments and map geometry are embedded. Only external source links require a network connection. Notes are saved in local browser storage when available; export your session for a portable backup.</p><button class="btn" data-action="tour-start">Take the five-stop tour →</button>`;}
class AtlasGlobe{
 constructor(canvas){this.canvas=canvas;this.ctx=canvas.getContext('2d',{alpha:false});this.lat=27;this.lon=-59;this.zoom=1.06;this.labels=true;this.groups=[];this.hover=null;this.drag=null;this.destroyed=false;this.dirty=true;this.target=null;this.listeners=[];this.stars=Array.from({length:120},(_,i)=>({x:((i*7717)%997)/997,y:((i*4199)%991)/991,r:i%9===0?1.15:.5}));this.resizeObserver=new ResizeObserver(()=>this.resize());this.resizeObserver.observe(canvas.parentElement);this.on('pointerdown',e=>{if(e.button!==0)return;this.drag={x:e.clientX,y:e.clientY,lat:this.lat,lon:this.lon,moved:false};this.canvas.setPointerCapture(e.pointerId);this.target=null;hideTip();});this.on('pointermove',e=>this.pointerMove(e));this.on('pointerup',e=>this.pointerUp(e));this.on('pointercancel',()=>this.drag=null);this.on('pointerleave',()=>{if(!this.drag){this.hover=null;hideTip();this.dirty=true;}});this.on('wheel',e=>{e.preventDefault();this.zoomTo(this.zoom*Math.exp(-e.deltaY*.001));},{passive:false});this.on('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','=','-','_'].includes(e.key)){e.preventDefault();this.target=null;if(e.key==='ArrowLeft')this.lon-=12;if(e.key==='ArrowRight')this.lon+=12;if(e.key==='ArrowUp')this.lat=Math.min(85,this.lat+9);if(e.key==='ArrowDown')this.lat=Math.max(-85,this.lat-9);if(e.key==='+'||e.key==='=')this.zoomTo(this.zoom*1.25);if(e.key==='-'||e.key==='_')this.zoomTo(this.zoom/1.25);this.dirty=true;}});this.resize();this.frame=()=>{if(this.destroyed)return;if(this.target){let dl=((this.target.lon-this.lon+540)%360)-180,da=this.target.lat-this.lat,dz=this.target.zoom-this.zoom;this.lon+=dl*.115;this.lat+=da*.115;this.zoom+=dz*.115;this.dirty=true;if(Math.abs(dl)+Math.abs(da)+Math.abs(dz)<.07){this.lon=this.target.lon;this.lat=this.target.lat;this.zoom=this.target.zoom;this.target=null;}}if(this.dirty){this.draw();this.dirty=false;}this.raf=requestAnimationFrame(this.frame);};this.raf=requestAnimationFrame(this.frame);}
 on(type,fn,opts){this.canvas.addEventListener(type,fn,opts);this.listeners.push([type,fn,opts]);}
 resize(){const parent=this.canvas.parentElement,nw=parent.clientWidth,nh=parent.clientHeight;if(this.w===nw&&this.h===nh)return;this.w=nw;this.h=nh;this.dpr=Math.min(window.devicePixelRatio||1,1.7);this.canvas.width=Math.round(this.w*this.dpr);this.canvas.height=Math.round(this.h*this.dpr);this.canvas.style.width=this.w+'px';this.canvas.style.height=this.h+'px';this.dirty=true;}
 destroy(){this.destroyed=true;cancelAnimationFrame(this.raf);this.resizeObserver.disconnect();this.listeners.forEach(([t,f,o])=>this.canvas.removeEventListener(t,f,o));hideTip();}
 project(lon,lat,mult=1){const r=Math.PI/180,la=lat*r,lo=(lon-this.lon)*r,cl=Math.cos(la),sl=Math.sin(la),sl0=this.sl0,cl0=this.cl0;const z=sl0*sl+cl0*cl*Math.cos(lo),x=cl*Math.sin(lo),y=cl0*sl-sl0*cl*Math.cos(lo);return{x:this.cx+this.radius*mult*x,y:this.cy-this.radius*mult*y,z};}
 projectNow(lon,lat){this.sl0=Math.sin(this.lat*Math.PI/180);this.cl0=Math.cos(this.lat*Math.PI/180);this.radius=Math.min(this.w,this.h)*.405*this.zoom;this.cx=this.w*.51;this.cy=this.h*.53;return this.project(lon,lat);}
 flyTo(lat,lon,zoom=1.6){this.target={lat,lon,zoom};if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){this.lat=lat;this.lon=lon;this.zoom=zoom;this.target=null;this.dirty=true;}}
 zoomTo(z){this.zoom=Math.min(7,Math.max(.78,z));if(this.target)this.target.zoom=this.zoom;this.dirty=true;}
 pointerMove(e){if(this.drag){const dx=e.clientX-this.drag.x,dy=e.clientY-this.drag.y;if(Math.abs(dx)+Math.abs(dy)>4)this.drag.moved=true;this.lon=this.drag.lon-dx*.26/this.zoom;this.lat=Math.max(-87,Math.min(87,this.drag.lat+dy*.23/this.zoom));this.dirty=true;return;}const r=this.canvas.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;let hit=this.groups.filter(g=>Math.hypot(g.x-x,g.y-y)<g.r+8).sort((a,b)=>Math.hypot(a.x-x,a.y-y)-Math.hypot(b.x-x,b.y-y))[0];if(hit!==this.hover){this.hover=hit||null;this.dirty=true;this.canvas.style.cursor=hit?'pointer':'grab';}if(hit){const s=hit.sites[0],d=s[state.globeLayer];showTip(e.clientX,e.clientY,hit.sites.length>1?`<b>${hit.sites.length} nearby records</b><br>${hit.sites.slice(0,4).map(x=>esc(x.name)).join('<br>')}<br><small>Click to choose a dossier · zoom to separate</small>`:`<b>${esc(s.name)}</b><br>${esc(s.owner_label)}<br>${d?fmt(d.it_mw)+' MW IT · '+(state.globeLayer==='target'?'projected':'modeled snapshot'):'AI IT power not established'}<br><small>${esc(s.location)} · approximate</small>`);}else hideTip();}
 pointerUp(e){if(!this.drag)return;const moved=this.drag.moved;this.drag=null;try{this.canvas.releasePointerCapture(e.pointerId)}catch{}if(moved)return;const r=this.canvas.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top,hit=this.groups.filter(g=>Math.hypot(g.x-x,g.y-y)<g.r+8).sort((a,b)=>Math.hypot(a.x-x,a.y-y)-Math.hypot(b.x-x,b.y-y))[0];hideTip();if(hit){if(hit.sites.length===1)openDrawer('site',hit.sites[0].id);else{const lat=hit.sites.reduce((n,s)=>n+s.lat,0)/hit.sites.length,lon=hit.sites.reduce((n,s)=>n+s.lon,0)/hit.sites.length;this.flyTo(lat,lon,Math.min(6,this.zoom*1.5));openDrawer('cluster',hit.sites.map(s=>s.id).join('|'));}}}
 draw(){const c=this.ctx,w=this.w,h=this.h;if(!w||!h)return;c.setTransform(this.dpr,0,0,this.dpr,0,0);c.clearRect(0,0,w,h);let bg=c.createLinearGradient(0,0,w,h);bg.addColorStop(0,'#0b1722');bg.addColorStop(.55,'#0d1c28');bg.addColorStop(1,'#0b1521');c.fillStyle=bg;c.fillRect(0,0,w,h);for(const s of this.stars){c.globalAlpha=.25;c.fillStyle='#b0cfdf';c.beginPath();c.arc(s.x*w,s.y*h,s.r,0,Math.PI*2);c.fill();}c.globalAlpha=1;this.sl0=Math.sin(this.lat*Math.PI/180);this.cl0=Math.cos(this.lat*Math.PI/180);this.radius=Math.min(w,h)*.405*this.zoom;this.cx=w*.51;this.cy=h*.53;const R=this.radius,cx=this.cx,cy=this.cy;
 c.save();let halo=c.createRadialGradient(cx,cy,R*.96,cx,cy,R*1.11);halo.addColorStop(0,'#5aa2a030');halo.addColorStop(.3,'#5aa2a022');halo.addColorStop(1,'#5aa2a000');c.fillStyle=halo;c.beginPath();c.arc(cx,cy,R*1.11,0,Math.PI*2);c.fill();c.restore();
 c.save();c.beginPath();c.arc(cx,cy,R,0,Math.PI*2);c.clip();let ocean=c.createRadialGradient(cx-R*.35,cy-R*.4,R*.05,cx+R*.1,cy+R*.1,R*1.4);ocean.addColorStop(0,'#1c3744');ocean.addColorStop(.55,'#142c39');ocean.addColorStop(1,'#081721');c.fillStyle=ocean;c.fillRect(cx-R,cy-R,R*2,R*2);
 const pathLine=(pts,stroke,width)=>{c.beginPath();let last=false;for(let a of pts){const p=this.project(a[0],a[1]);if(p.z>0){if(last)c.lineTo(p.x,p.y);else c.moveTo(p.x,p.y);last=true;}else last=false;}c.strokeStyle=stroke;c.lineWidth=width;c.stroke();};
 for(let lat=-60;lat<=60;lat+=30)pathLine(Array.from({length:121},(_,i)=>[-180+i*3,lat]),'#3f6b7629',.65);for(let lon=-180;lon<180;lon+=30)pathLine(Array.from({length:91},(_,i)=>[lon,-90+i*2]),'#3f6b7629',.65);
 for(const [lon,lat] of W.dots){const p=this.project(lon,lat);if(p.z<=0)continue;c.globalAlpha=.4+p.z*.35;c.fillStyle='#81b5b1';const size=Math.min(2.4,.65+this.zoom*.24)*(.65+.35*p.z);c.fillRect(p.x-size/2,p.y-size/2,size,size);}c.globalAlpha=1;
 for(const line of W.lines)pathLine(line,'#84b4b754',.7);
 let shade=c.createLinearGradient(cx-R,cy-R,cx+R,cy+R*.65);shade.addColorStop(0,'#102f3600');shade.addColorStop(.5,'#05111b00');shade.addColorStop(1,'#010610ac');c.fillStyle=shade;c.fillRect(cx-R,cy-R,R*2,R*2);c.restore();c.strokeStyle='#83bdc047';c.lineWidth=1;c.beginPath();c.arc(cx,cy,R,0,Math.PI*2);c.stroke();
 // Markers preserve every record; proximity clustering is purely visual.
 const ss=(state.view==='overview'?D.sites:filteredSites()).filter(s=>s.lat!=null),visible=[];for(const s of ss){const p=this.project(s.lon,s.lat);if(p.z>.02&&p.x>-30&&p.x<w+30&&p.y>-30&&p.y<h+30)visible.push({s,p});}
 const groups=[];for(const {s,p} of visible){let g=groups.find(g=>Math.hypot(g.x-p.x,g.y-p.y)<17);if(g){g.sites.push(s);g.x=(g.x*(g.sites.length-1)+p.x)/g.sites.length;g.y=(g.y*(g.sites.length-1)+p.y)/g.sites.length;}else groups.push({x:p.x,y:p.y,z:p.z,sites:[s],r:5});}
 groups.forEach(g=>{const s=g.sites[0],num=g.sites.length,d=s[state.globeLayer];let value=state.marker==='compute'?d?.h100e_k:state.marker==='cost'?(d?.cost_b||0)*25:state.marker==='equal'?100:d?.it_mw;g.r=num>1?Math.min(14,7+Math.log2(num)*2):Math.min(12,3.4+Math.sqrt(value||0)*.16);const col=num>1?'#afe3d0':color(s);const hover=this.hover&&this.hover.sites.some(x=>g.sites.includes(x));c.save();c.shadowColor=col;c.shadowBlur=hover?20:9;c.lineWidth=hover?2:1;c.strokeStyle=col;c.fillStyle=num>1?'#1a443e':d?col:'#122532';c.beginPath();c.arc(g.x,g.y,g.r,0,Math.PI*2);c.fill();c.stroke();c.shadowBlur=0;if(num>1){c.fillStyle='#d3f8e7';c.font='10px ui-monospace,monospace';c.textAlign='center';c.textBaseline='middle';c.fillText(num,g.x,g.y+.5);}else if(d){c.fillStyle='#e8fff3';c.beginPath();c.arc(g.x,g.y,Math.max(1,g.r*.19),0,Math.PI*2);c.fill();}if(hover){c.globalAlpha=.45;c.beginPath();c.arc(g.x,g.y,g.r+6,0,Math.PI*2);c.stroke();}c.restore();});
 this.groups=groups;const labelBoxes=[];if(this.labels){const ls=groups.filter(g=>g.sites.length===1).sort((a,b)=>(b.sites[0][state.globeLayer]?.it_mw||0)-(a.sites[0][state.globeLayer]?.it_mw||0)).slice(0,this.zoom>2?18:9);for(const g of ls){let txt=g.sites[0].name;c.font='10px -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif';let tw=c.measureText(txt).width,xx=g.x+g.r+7,yy=g.y+3;if(xx+tw>w-12)xx=g.x-g.r-tw-7;if(yy<82||yy>h-103||labelBoxes.some(b=>Math.abs(b.y-yy)<16&&xx<b.x+b.w+12&&xx+tw>b.x-12))continue;labelBoxes.push({x:xx,y:yy,w:tw});c.fillStyle='#b6d2d5';c.textAlign='left';c.fillText(txt,xx,yy);}}
 const live=$('#globe-live');if(live)live.textContent=`${ss.length} mapped records · ${visible.length} on this hemisphere`;const gp=$('#geo-position');if(gp)gp.textContent=`${Math.abs(this.lat).toFixed(1)}°${this.lat>=0?'N':'S'}  ${Math.abs(((this.lon+540)%360)-180).toFixed(1)}°${(((this.lon+540)%360)-180)>=0?'E':'W'}  ·  ${this.zoom.toFixed(1)}×  ·  approximate anchors`;
 }
}
function showTip(x,y,html){const t=$('#tooltip');t.innerHTML=html;t.style.display='block';t.style.left=Math.min(window.innerWidth-285,x+17)+'px';t.style.top=Math.max(10,Math.min(window.innerHeight-t.offsetHeight-12,y+13))+'px';}
function hideTip(){$('#tooltip').style.display='none';}
function openSearch(){lastFocused=document.activeElement;$('#search-modal').hidden=false;$('#global-search').value='';searchAll('');setTimeout(()=>$('#global-search').focus(),15);}
function closeSearch(){$('#search-modal').hidden=true;if(lastFocused?.isConnected)lastFocused.focus({preventScroll:true});}
const searchDocs=A.reports.flatMap((r,ri)=>r.sections.map((s,si)=>({ri,si,title:s.title,text:s.blocks.map(b=>b.text||b.rows?.flat().join(' ')||'').join(' ')})));
function searchAll(q){q=q.trim().toLowerCase();let out=[];if(!q){out=STOPS.filter(s=>s.site).map(s=>({kind:'FACILITY',title:s.site().name,text:s.title,action:'site',id:s.site().id}));out.push({kind:'GUIDE',title:'Reading the evidence',text:'How power, costs and source confidence fit together.',action:'method',id:''});}else{for(const s of D.sites)if(JSON.stringify([s.name,s.owner_label,s.location,s.hardware,s.facts,s.raw]).toLowerCase().includes(q))out.push({kind:'FACILITY',title:s.name,text:s.owner_label+' · '+s.location,action:'site',id:s.id});for(const c of D.companies)if(JSON.stringify([c.name,c.ticker,c.role,c.thesis]).toLowerCase().includes(q))out.push({kind:'COMPANY',title:c.name,text:c.role+' · '+c.region,action:'company',id:c.id});for(const s of D.sources)if(JSON.stringify(s).toLowerCase().includes(q))out.push({kind:'SOURCE',title:s.id+' · '+s.issuer,text:s.title,action:'source',id:s.id});for(const c of D.contracts)if(JSON.stringify(c).toLowerCase().includes(q))out.push({kind:'CONTRACT',title:c.vendor+' / '+c.counterparty,text:c.capacity_type+' · '+c.status,action:'contract',id:c.id});for(const c of D.costs)if(JSON.stringify(c).toLowerCase().includes(q))out.push({kind:'COST',title:c.benchmark,text:c.layer,action:'cost',id:c.id});for(const d of searchDocs){let i=d.text.toLowerCase().indexOf(q);if(i!==-1||d.title.toLowerCase().includes(q))out.push({kind:'REPORT',title:d.title,text:d.text.substring(Math.max(0,i-55),Math.max(0,i-55)+190),action:'search-report',id:d.ri+'|'+d.si});}let cellCount=0;for(let bi=0;bi<A.workbooks.length;bi++)for(let si=0;si<A.workbooks[bi].sheets.length;si++){const sh=A.workbooks[bi].sheets[si];for(const c of sh.cells)if(cellCount<25&&String(c.value??c.formula??'').toLowerCase().includes(q)){out.push({kind:'EXCEL',title:sh.name+'!'+c.address,text:String(c.value??c.formula).slice(0,190),action:'search-cell',id:bi+'|'+si+'|'+c.address});cellCount++;}}}
 const total=out.length;$('#search-results').innerHTML=(q?`<div class="command-hint">${total} matching records / sections${total>70?' · first 70 shown':''}</div>`:'<div class="command-hint">START EXPLORING</div>')+out.slice(0,70).map((r,i)=>`<button class="search-result" data-action="${r.action}" data-id="${esc(r.id)}"><span class="kind">${r.kind}</span><span><strong>${esc(r.title)}</strong><p>${esc(r.text)}</p></span></button>`).join('')||(q?'<div class="search-empty">No results found. Try a shorter name or source ID.</div>':'');if(!out.length)$('#search-results').innerHTML='<div class="search-empty">No results found. Try a shorter name, location or source ID.</div>';}
function startTour(i=0){closeDrawer();closeSearch();state.tour=i;showTourStop();}
function showTourStop(){const s=STOPS[state.tour];if(!s){endTour();return;}if(s.view){state.costTab='scenario';navigate(s.view);}else{state.filter={q:'',company:'all',country:'all',review:'all',stage:'all'};state.globeLayer='snapshot';navigate('globe');const p=s.site();globe.flyTo(p.lat,p.lon,1.9);}renderTour();}
function renderTour(){const s=STOPS[state.tour];if(!s){$('#tour').hidden=true;return;}$('#tour').hidden=false;$('#tour').innerHTML=`<button class="text-button tour-close" data-action="tour-close" aria-label="End guided tour">✕</button><div class="eyebrow">${s.sub}</div><h3>${s.title}</h3><p>${s.text} ${srefs(s.sources)}</p>${s.site?`<button class="text-button" data-action="site" data-id="${s.site().id}">Open the facility dossier ↗</button>`:''}<div class="tour-progress"><div style="width:${(state.tour+1)/STOPS.length*100}%"></div></div><div class="tour-actions"><button class="text-button" data-action="tour-prev" ${state.tour===0?'disabled':''}>← Previous</button><span class="cell-sub">${state.tour+1} / ${STOPS.length}</span><button class="btn small primary" data-action="tour-next">${state.tour===STOPS.length-1?'Finish tour ✓':'Next stop →'}</button></div>`;}
function endTour(){state.tour=-1;$('#tour').hidden=true;}
function download(name,data,mime='application/json'){const blob=data instanceof Blob?data:new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type:mime});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),20000);toast('Export prepared: '+name);}
function csv(rows){return '\ufeff'+rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');}
function exportSites(){const h=['id','facility','companies','location','country','latitude_approx','longitude_approx','coordinate_precision','evidence','snapshot_it_mw','snapshot_h100e_k','snapshot_modeled_capex_usd_b','snapshot_date','target_it_mw','target_h100e_k','target_date','sources','caveats'];download('compute_atlas_filtered_facilities.csv',csv([h,...filteredSites().map(s=>[s.id,s.name,s.owner_label,s.location,s.country,s.lat,s.lon,s.coordinate_precision,s.review,s.snapshot?.it_mw,s.snapshot?.h100e_k,s.snapshot?.cost_b,s.snapshot?.date,s.target?.it_mw,s.target?.h100e_k,s.target?.date,s.sources.join(';'),s.caveats.join(' | ')])]),'text/csv;charset=utf-8');}
function downloadOriginal(name){const files=JSON.parse($('#original-files').textContent),b64=files[name];if(!b64){toast('This original attachment is not embedded.');return;}const s=atob(b64),b=new Uint8Array(s.length);for(let i=0;i<s.length;i++)b[i]=s.charCodeAt(i);const ext=name.split('.').pop(),mime=({pdf:'application/pdf',xlsx:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',docx:'application/vnd.openxmlformats-officedocument.wordprocessingml.document',json:'application/json'})[ext]||'application/octet-stream';download(name,new Blob([b],{type:mime}));}
function toggleCompare(id){if(state.compare.includes(id))state.compare=state.compare.filter(x=>x!==id);else{if(state.compare.length>=4){toast('Choose up to four companies for a readable comparison.');return false;}state.compare.push(id);}save();return true;}
function rememberFilterFocus(fn,id){const el=$('#'+id),start=el?.selectionStart,end=el?.selectionEnd;fn();const ne=$('#'+id);if(ne){ne.focus({preventScroll:true});try{ne.setSelectionRange(start,end)}catch{}}}
let debounceTimer;
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id;if(b.closest('#search-results'))closeSearch();if(b.closest('.raw-details summary')&&a.startsWith('export'))e.preventDefault();switch(a){
case 'nav':if(state.tour>=0)endTour();navigate(id);break;
case 'menu':$('#sidebar').classList.toggle('open');break;
case 'search':openSearch();break;case 'close-search':closeSearch();break;
case 'help':openDrawer('help');break;case 'method':openDrawer('method');break;
case 'site':openDrawer('site',id);break;case 'company':openDrawer('company',id);break;case 'source':openDrawer('source',id);break;case 'cost':openDrawer('cost',id);break;case 'contract':openDrawer('contract',id);break;case 'hardware':openDrawer('hardware',id);break;case 'footnote':openDrawer('footnote',id);break;
case 'close-drawer':closeDrawer();break;case 'drawer-back':{const p=state.drawerHistory.pop();if(p)openDrawer(p.kind,p.id,{back:true});break;}
case 'favorite':{if(isSaved(id))saved.favorites=saved.favorites.filter(x=>x!==id);else saved.favorites.push(id);save();$$(`.star-button[data-id="${CSS.escape(id)}"]`).forEach(el=>{el.textContent=isSaved(id)?'★':'☆';el.classList.toggle('saved',isSaved(id));el.setAttribute('aria-pressed',String(isSaved(id)));});if(state.view==='watchlist'&&!state.drawer)render();toast(isSaved(id)?'Added to your local research shelf.':'Removed from your research shelf.');break;}
case 'reset-filters':state.filter={q:'',company:'all',country:'all',review:'all',stage:'all'};render();break;
case 'sort':state.sort=id;render();break;case 'site-layout':state.layout=id;render();break;
case 'globe-layer':state.globeLayer=id;$$('[data-action="globe-layer"]').forEach(el=>el.classList.toggle('active',el.dataset.id===id));if(globe)globe.dirty=true;if($('#globe-list'))$('#globe-list').innerHTML=siteItems(filteredSites());break;
case 'globe-labels':if(globe){globe.labels=!globe.labels;globe.dirty=true;b.classList.toggle('active',globe.labels);}break;
case 'zoom':if(globe)globe.zoomTo(globe.zoom*(id==='in'?1.35:1/1.35));break;
case 'fly':if(globe){const p={americas:[31,-97,1.75],europe:[50,12,1.65],asia:[31,109,1.9]}[id];globe.flyTo(...p);}break;
case 'globe-home':if(globe)globe.flyTo(27,-59,1.06);break;
case 'globe-fullscreen':{const el=$('.globe-panel');if(document.fullscreenElement)document.exitFullscreen?.();else el?.requestFullscreen?.().catch(()=>toast('Full-screen mode is not available in this browser.'));break;}
case 'locate':{const s=site(id);closeDrawer();state.filter={q:'',company:'all',country:'all',review:'all',stage:'all'};navigate('globe');if(globe&&s.lat!=null)globe.flyTo(s.lat,s.lon,2.4);toast('Located at an approximate regional anchor; select its marker or list entry.');break;}
case 'filter-company':state.filter={q:'',company:id,country:'all',review:'all',stage:'all'};navigate('facilities');break;
case 'company-region':state.companyRegion=id;render();break;case 'company-region-link':state.companyRegion=id;navigate('companies');break;
case 'toggle-compare':toggleCompare(id);if(state.drawer?.kind==='company')openDrawer('company',id,{back:true});else render();break;
case 'clear-compare':state.compare=[];save();render();break;
case 'cost-tab':state.costTab=id;render();break;
case 'reset-scenario':Object.assign(scenario,{capex:37.883,share:69,itlife:5,faclife:14,util:71,pue:1.18,power:.08,rate:8,opex:.5,eff:1.378106});render();break;
case 'heat':scenario.itlife=+b.dataset.life;scenario.util=+b.dataset.util;$('#s-itlife').value=scenario.itlife;$('#s-util').value=scenario.util;updateScenario();break;
case 'invest-company':state.invest=id;navigate('investment');break;
case 'report-section':state.section=+id;render();window.scrollTo({top:0,behavior:'instant'});break;case 'report-next':state.section++;render();window.scrollTo({top:0,behavior:'instant'});break;case 'report-prev':state.section--;render();window.scrollTo({top:0,behavior:'instant'});break;
case 'data-tab':state.dataTab=id;if(state.view!=='data')navigate('data');else render();break;
case 'cell':openDrawer('cell',id);break;
case 'search-report':{const [ri,si]=id.split('|').map(Number);state.report=ri;state.section=si;state.reportQ='';navigate('reports');break;}
case 'search-cell':{const [bi,si,addr]=id.split('|');state.book=+bi;state.sheet=+si;state.dataTab='workbooks';navigate('data');openDrawer('cell',addr);break;}
case 'story':if(id==='0')openDrawer('site',D.sites.find(s=>s.name==='New Carlisle').id);if(id==='1')openDrawer('site',D.sites.find(s=>s.name==='Helios').id);if(id==='2'){state.filter={q:'',company:'all',country:'China',review:'all',stage:'all'};navigate('globe');globe.flyTo(31,110,1.8);}break;
case 'tour-start':startTour();break;case 'tour-at':startTour(+id);break;case 'tour-prev':if(state.tour>0){state.tour--;showTourStop();}break;case 'tour-next':state.tour++;if(state.tour>=STOPS.length){endTour();toast('Tour complete. Explore any record or save it to your shelf.');}else showTourStop();break;case 'tour-close':endTour();break;
case 'print':window.print();break;
case 'original-file':downloadOriginal(id);break;
case 'export-all':download('compute_atlas_enriched_data.json',D);break;case 'export-section':download('compute_atlas_'+id+'.json',D[id]);break;case 'site-export':download(id+'.json',site(id));break;case 'export-sites':exportSites();break;
case 'export-scenario':download('compute_atlas_economics_scenario.json',{assumptions:scenario,results:calculateScenario(),scope:'Hypothetical annuity-cost model per IT GW; not an issuer forecast'});break;
case 'export-sheet':{const sh=A.workbooks[state.book].sheets[state.sheet],m=new Map(sh.cells.map(c=>[c.address,c]));download(sh.name+'_original_cached_values.csv',csv(Array.from({length:sh.max_row},(_,r)=>Array.from({length:sh.max_col},(_,c)=>m.get(colName(c+1)+(r+1))?.value??''))),'text/csv;charset=utf-8');break;}
case 'export-legacy':download('original_model_'+state.book+'.json',A.legacy[state.book]);break;case 'export-model-key':download('original_'+id+'.json',A.legacy[state.book][id]);break;
case 'export-session':download('compute_atlas_research_session.json',{version:3,exported:new Date().toISOString(),favorites:saved.favorites,notes:saved.notes,compare:state.compare});break;
case 'import-session':{const inp=document.createElement('input');inp.type='file';inp.accept='.json';inp.onchange=async()=>{try{const x=JSON.parse(await inp.files[0].text());if(!Array.isArray(x.favorites)||!x.notes||typeof x.notes!=='object')throw Error('Invalid session format');saved.favorites=x.favorites.filter(id=>site(id));saved.notes=Object.fromEntries(Object.entries(x.notes).filter(([id,v])=>site(id)&&typeof v==='string'));state.compare=Array.isArray(x.compare)?x.compare.filter(id=>company(id)).slice(0,4):[];save();render();toast('Research session imported.');}catch(err){toast('Could not import this file: '+err.message);}};inp.click();break;}
}});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.filter){state.filter[el.dataset.filter]=el.value;render();}else if(el.dataset.compare){if(!toggleCompare(el.dataset.compare))el.checked=false;render();}else if(el.id==='marker-metric'){state.marker=el.value;if(globe)globe.dirty=true;}else if(el.id==='cost-layer'){state.costLayer=el.value;render();}else if(el.id==='invest-company'){state.invest=el.value;render();}else if(el.id==='report-select'){state.report=+el.value;state.section=0;render();}else if(el.id==='book-select'){state.book=+el.value;state.sheet=0;render();}else if(el.id==='sheet-select'){state.sheet=+el.value;render();}else if(el.id==='model-select'){state.book=+el.value;render();}});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.scenario){scenario[el.dataset.scenario]=+el.value;updateScenario();return;}if(el.id.startsWith('v-')){updateInvestment();return;}if(el.dataset.note){saved.notes[el.dataset.note]=el.value;save();return;}if(el.id==='global-search'){clearTimeout(debounceTimer);debounceTimer=setTimeout(()=>searchAll(el.value),100);return;}const map={'site-query':['filter','q'],'company-query':['companyQ'],'report-query':['reportQ'],'data-query':['dataQ'],'cost-query':['costQ']};if(map[el.id]){const p=map[el.id];if(p.length===2)state[p[0]][p[1]]=el.value;else state[p[0]]=el.value;clearTimeout(debounceTimer);debounceTimer=setTimeout(()=>rememberFilterFocus(()=>render(),el.id),170);}});
$('#drawer-scrim').addEventListener('click',()=>closeDrawer());$('#search-modal').addEventListener('click',e=>{if(e.target.id==='search-modal')closeSearch();});
document.addEventListener('keydown',e=>{const input=/INPUT|TEXTAREA|SELECT/.test(document.activeElement?.tagName);if((e.key==='/'&&!input)||((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k')){e.preventDefault();openSearch();return;}if(e.key==='Escape'){if(!$('#search-modal').hidden)closeSearch();else if(!$('#drawer').hidden)closeDrawer();else if(state.tour>=0)endTour();$('#sidebar').classList.remove('open');return;}if(e.key==='Enter'&&e.target.matches('tr[data-action],g[data-action],td[data-action]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}if(e.key==='Enter'&&e.target.id==='global-search'){$('#search-results .search-result')?.click();}if(e.key==='Tab'){const modal=!$('#search-modal').hidden?$('#search-modal'):!$('#drawer').hidden?$('#drawer'):null;if(modal){const focusable=$$('button:not([disabled]),a[href],input,textarea,select,[tabindex="0"]',modal).filter(el=>el.offsetParent!==null);const first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}}});
function routeFromHash(){const h=location.hash.slice(1),parts=h.split('/'),kind=parts[0],id=decodeURIComponent(parts.slice(1).join('/'));if(['site','company','source'].includes(kind)&&id){navigate(kind==='site'?'globe':kind==='company'?'companies':'data',{hash:true});openDrawer(kind,id);}else navigate(h||'overview',{hash:true});}
window.addEventListener('hashchange',routeFromHash);
window.addEventListener('error',e=>console.error('Atlas error:',e.message));
// Explicit QA hooks expose the same data/state, with no remote dependencies or telemetry.
window.ATLAS={data:D,archive:A,state,scenario,getGlobe:()=>globe,calculateScenario,navigate,openDrawer,filteredSites};
routeFromHash();
